/* ---------- France : régions approfondies ---------- */
const D52 = [
{ id:'welsh-rarebit-nordiste', c:'eu', lat:50.995, lon:2.295, base:4, prep:15, cook:20, diff:1, tags:['cheese','comfort','fast'],
  art:{v:'plate',bg:'#2f2a20',plate:'#f2e6c8',style:'flat',food:['#e0b45a','#c98a2c','#c9a878','#f0d89a'],garnish:'#7fae6a'},
  n:{fr:'Welsh',en:'Welsh'},
  p:{fr:'Dunkerque, Nord, France',en:'Dunkirk, Nord, France'},
  d:{fr:"Du cheddar fondu à la bière brune, versé sur une tartine tapissée de jambon et couronné d'un œuf. Rapporté par les ouvriers gallois des mines du Nord, il est devenu le plat des estaminets de la côte d'Opale.",
     en:"Cheddar melted in brown ale, poured over toast lined with ham and crowned with an egg. Brought by Welsh miners to the north, it became the dish of the Opal Coast taverns."},
  i:[['cheddar_cheese',600,'g'],['brown_ale',200,'ml'],['dijon_mustard',3,'tbsp'],['white_bread',4,'slice'],['ham',200,'g'],['egg',4,'pc'],['worcestershire',2,'tbsp'],['potato',800,'g'],['frying_oil',600,'ml'],['pepper',null,'']],
  s:{fr:["Taillez le cheddar en dés et faites-le fondre très doucement dans la bière, sans jamais bouillir : trop chaud, il file et se sépare.","Ajoutez la moutarde et le worcestershire, et poivrez généreusement.","Faites griller le pain, tapissez-le de jambon et rangez le tout dans des plats individuels.","Nappez de fromage fondu et passez 8 minutes sous le gril, jusqu'à ce que la surface cloque et brunisse.","Posez un œuf au plat sur chaque welsh et servez avec des frites, à la mode du Nord."],
     en:["Dice the cheddar and melt it very gently in the ale, never boiling: too hot and it strings and splits.","Add the mustard and Worcestershire sauce, and season well with pepper.","Toast the bread, line it with ham and set everything in individual dishes.","Cover with the melted cheese and give it 8 minutes under the grill, until the surface blisters and browns.","Set a fried egg on each welsh and serve with chips, as they do in the north."]} },

{ id:'ficelle-picarde', c:'eu', lat:49.894, lon:2.296, base:4, prep:30, cook:25, diff:2, tags:['cheese','bake','comfort'],
  art:{v:'plate',bg:'#2f3326',plate:'#f4ecd8',style:'roll',food:['#f0e8d0','#e8dcc0','#c9924a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Ficelle picarde',en:'Ficelle picarde'},
  p:{fr:'Amiens, Picardie, France',en:'Amiens, Picardy, France'},
  d:{fr:"Une crêpe roulée sur du jambon et des champignons, gratinée sous une crème au fromage. Créée en 1950 pour une foire gastronomique d'Amiens, elle est devenue l'entrée dominicale de toute la Picardie.",
     en:"A pancake rolled around ham and mushrooms, gratinated under a cheese cream. Created in 1950 for a food fair in Amiens, it became the Sunday starter of the whole of Picardy."},
  i:[['flour',150,'g'],['egg',3,'pc'],['whole_milk',400,'ml'],['butter',80,'g'],['ham',8,'slice'],['button_mushrooms',400,'g'],['shallot',3,'pc'],['heavy_cream',300,'ml'],['gruyere_cheese',150,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites une pâte à crêpes lisse et laissez-la reposer une heure : sans repos, les crêpes se déchirent au roulage.","Faites suer les champignons émincés avec l'échalote jusqu'à ce que toute leur eau soit partie.","Liez-les d'un tiers de la crème et laissez refroidir.","Garnissez chaque crêpe d'une tranche de jambon et d'un peu de duxelles, puis roulez-la serré.","Rangez-les dans un plat beurré, nappez du reste de crème, parsemez de gruyère et gratinez 20 minutes à 200 °C."],
     en:["Make a smooth pancake batter and rest it for an hour: without resting, the pancakes tear when rolled.","Sweat the sliced mushrooms with the shallot until all their water has gone.","Bind them with a third of the cream and let it cool.","Fill each pancake with a slice of ham and a little duxelles, then roll it tightly.","Pack them in a buttered dish, coat with the remaining cream, scatter gruyère and gratinate for 20 minutes at 200°C."]} },

{ id:'flamiche-aux-poireaux', c:'eu', lat:50.129, lon:3.253, base:6, prep:40, cook:45, diff:2, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f0e8d0','#7fae5a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Flamiche aux poireaux',en:'Leek flamiche'},
  p:{fr:'Dinant, Ardennes, France',en:'Dinant, Ardennes, France'},
  d:{fr:"Une tourte fermée de poireaux fondus à la crème, sans une trace de lardons. Le poireau du Nord se cuit ici jusqu'à devenir presque une confiture : c'est cette longue fonte qui fait tout, pas la pâte.",
     en:"A closed pie of leeks softened in cream, without a trace of bacon. The northern leek is cooked here almost to a jam: that long melting is what matters, not the pastry."},
  i:[['flour',350,'g'],['butter',200,'g'],['egg',3,'pc'],['leek',1.5,'kg'],['heavy_cream',300,'ml'],['nutmeg',1,'pinch'],['ice_water',80,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Sablez la farine et 175 g de beurre, liez d'un jaune et d'eau glacée, et laissez reposer une heure au frais.","Émincez les blancs de poireau très finement et faites-les fondre 40 minutes à couvert dans le beurre restant, sans coloration.","Ils doivent perdre les trois quarts de leur volume et devenir translucides : à ce stade seulement, salez.","Ajoutez la crème et deux œufs battus hors du feu, et râpez la muscade.","Chemisez un moule de pâte, garnissez, couvrez d'un second disque, soudez les bords et enfournez 45 minutes à 190 °C."],
     en:["Rub the flour and 175 g of butter together, bind with a yolk and iced water, and rest for an hour in the cold.","Slice the leek whites very finely and melt them for 40 minutes, covered, in the remaining butter, without colouring.","They should lose three quarters of their volume and turn translucent: only then salt them.","Add the cream and two beaten eggs off the heat, and grate over the nutmeg.","Line a tin with pastry, fill it, cover with a second disc, seal the edges and bake for 45 minutes at 190°C."]} },

{ id:'caudiere-berckoise', c:'eu', lat:50.404, lon:1.601, base:6, prep:30, cook:45, diff:2, tags:['sea','soup','comfort'],
  art:{v:'pot',bg:'#26384a',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#e8dcc0','#e0b45a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Caudière berckoise',en:'Berck caudière'},
  p:{fr:'Berck-sur-Mer, Pas-de-Calais, France',en:'Berck-sur-Mer, Pas-de-Calais, France'},
  d:{fr:"La bouillabaisse du Nord : poissons de la Manche, pommes de terre et crème, sans safran ni tomate. Le nom vient du chaudron, la caudière, que les pêcheurs de Berck posaient sur le sable au retour de la marée.",
     en:"The bouillabaisse of the north: Channel fish, potatoes and cream, without saffron or tomato. The name comes from the cauldron, the caudière, that Berck fishermen set on the sand when the tide returned."},
  i:[['whiting',600,'g'],['cod_fillet',600,'g'],['mussels',1,'kg'],['potato',800,'g'],['onion',3,'pc'],['leek',2,'pc'],['heavy_cream',300,'ml'],['white_wine',300,'ml'],['butter',80,'g'],['bay_leaf',2,'pc'],['thyme',3,'sprig'],['parsley',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Ouvrez les moules au vin blanc, décoquillez-les et filtrez soigneusement leur jus à travers un linge.","Faites fondre l'oignon et le poireau au beurre sans les colorer, ajoutez les pommes de terre en rondelles épaisses.","Mouillez du jus de moules allongé d'eau, ajoutez le thym et le laurier, et cuisez 20 minutes.","Coupez le feu et glissez les poissons en gros morceaux : ils pocheront dans la chaleur résiduelle, 8 minutes.","Ajoutez la crème et les moules, réchauffez sans bouillir, et couvrez de persil. Servez avec du pain grillé."],
     en:["Open the mussels in white wine, shell them and strain their liquor carefully through a cloth.","Soften the onion and leek in butter without colouring, then add the potatoes in thick slices.","Moisten with the mussel liquor let down with water, add the thyme and bay, and cook for 20 minutes.","Cut the heat and slide in the fish in large pieces: they poach in the residual warmth, 8 minutes.","Add the cream and the mussels, warm through without boiling, and cover with parsley. Serve with toast."]} },

{ id:'salade-au-lard-vosgienne', c:'eu', lat:48.171, lon:6.449, base:4, prep:20, cook:15, diff:1, tags:['pork','fast','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'salad',food:['#7fae5a','#e0b45a','#8f5a3a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Salade au lard des Vosges',en:'Vosges warm bacon salad'},
  p:{fr:'Gérardmer, Vosges, France',en:'Gérardmer, Vosges, France'},
  d:{fr:"Des pissenlits ou de la mâche arrosés de lard chaud et de son vinaigre déglacé, avec des pommes de terre tièdes et un œuf mollet. On verse la poêle brûlante sur la salade : elle doit siffler.",
     en:"Dandelion or lamb's lettuce dressed with hot bacon and its deglazing vinegar, with warm potatoes and a soft-boiled egg. The scorching pan is poured over the leaves: they should hiss."},
  i:[['dandelion_greens',300,'g'],['smoked_bacon',250,'g'],['potato',600,'g'],['egg',4,'pc'],['white_wine_vinegar',60,'ml'],['shallot',2,'pc'],['munster',150,'g'],['walnut_oil',3,'tbsp'],['croutons',100,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Lavez les pissenlits à plusieurs eaux et essorez-les à fond : une salade mouillée refuse la vinaigrette chaude.","Faites cuire les pommes de terre en robe des champs et pelez-les tièdes.","Faites rissoler les lardons à sec jusqu'à ce qu'ils croustillent, ajoutez l'échalote hors du feu.","Déglacez au vinaigre — la poêle doit fumer — et versez immédiatement sur la salade, en remuant.","Ajoutez les pommes de terre en rondelles, les croûtons, le munster en dés et un œuf mollet par assiette."],
     en:["Wash the dandelion in several changes of water and dry it thoroughly: wet leaves refuse a hot dressing.","Boil the potatoes in their skins and peel them while warm.","Fry the bacon dry until crisp, and add the shallot off the heat.","Deglaze with vinegar — the pan should smoke — and pour it over the leaves at once, tossing.","Add the sliced potatoes, croutons, diced Munster and one soft-boiled egg per plate."]} },

{ id:'pate-lorrain', c:'eu', lat:48.590, lon:6.494, base:6, prep:50, cook:45, diff:2, tags:['pork','bake','sunday'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#8f5a3a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Pâté lorrain',en:'Pâté lorrain'},
  p:{fr:'Baccarat, Lorraine, France',en:'Baccarat, Lorraine, France'},
  d:{fr:"Un chausson de pâte feuilletée farci de porc et de veau marinés au vin gris de Toul. La marinade dure vingt-quatre heures : sans elle, la farce reste plate et la Lorraine ne la reconnaît pas.",
     en:"A puff pastry case filled with pork and veal marinated in vin gris from Toul. The marinade takes twenty-four hours: without it the filling stays flat, and Lorraine will not recognise it."},
  i:[['puff_pastry',600,'g'],['pork_shoulder',400,'g'],['veal_shoulder',300,'g'],['white_wine',250,'ml'],['shallot',3,'pc'],['garlic',3,'clove'],['parsley',4,'tbsp'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['egg',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez les viandes en dés de 1 cm au couteau : hachées, elles rendraient une farce compacte.","Faites-les mariner 24 heures au frais dans le vin blanc, l'échalote, l'ail, les herbes, le sel et beaucoup de poivre.","Égouttez-les soigneusement et jetez la marinade : gardée, elle détremperait le feuilletage.","Étalez la pâte en deux rectangles, garnissez le premier en laissant deux centimètres de bord, et couvrez du second.","Soudez, chiquetez les bords, dorez à l'œuf, percez une cheminée et enfournez 45 minutes à 200 °C."],
     en:["Cut the meats into 1 cm dice by knife: minced, they would make a dense filling.","Marinate them for 24 hours in the cold with the white wine, shallot, garlic, herbs, salt and plenty of pepper.","Drain them thoroughly and discard the marinade: kept, it would sog the pastry.","Roll the pastry into two rectangles, fill the first leaving a two-centimetre border, and cover with the second.","Seal, crimp the edges, glaze with egg, cut a steam hole and bake for 45 minutes at 200°C."]} },

{ id:'poulet-au-vinaigre', c:'eu', lat:45.764, lon:4.836, base:4, prep:20, cook:45, diff:2, tags:['poultry','comfort','sunday'],
  art:{v:'pot',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#e0b45a','#c9754a','#f0e8d0','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Poulet au vinaigre',en:'Chicken in vinegar'},
  p:{fr:'Lyon, France',en:'Lyon, France'},
  d:{fr:"Un poulet déglacé au vinaigre de vin, lié à la crème et à la tomate. Paul Bocuse en avait fait un plat de bouchon : l'acidité doit rester franche, on ne cherche pas à l'adoucir.",
     en:"Chicken deglazed with wine vinegar, finished with cream and tomato. Paul Bocuse made it a bouchon dish: the sharpness should stay frank, and is not meant to be softened."},
  i:[['chicken',1.6,'kg'],['red_wine_vinegar',150,'ml'],['white_wine',150,'ml'],['ripe_tomato',300,'g'],['tomato_paste',1,'tbsp'],['heavy_cream',200,'ml'],['garlic',10,'clove'],['shallot',4,'pc'],['butter',80,'g'],['tarragon',3,'tbsp'],['chicken_broth',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez le poulet en huit et faites-le colorer au beurre sur toutes ses faces, sans le brusquer.","Ajoutez l'ail en chemise et l'échalote, couvrez et laissez suer 10 minutes.","Versez le vinaigre et laissez-le réduire de moitié à découvert : c'est là que l'âcreté part et que le goût reste.","Ajoutez le vin, la tomate, le concentré et le fond, et laissez mijoter 30 minutes à couvert.","Retirez le poulet, montez la sauce à la crème et au beurre froid, et ajoutez l'estragon hors du feu."],
     en:["Joint the chicken into eight and colour it in butter on all sides, without hurrying.","Add the unpeeled garlic and the shallot, cover and sweat for 10 minutes.","Pour in the vinegar and reduce it by half uncovered: this is where the harshness goes and the flavour stays.","Add the wine, tomato, tomato paste and stock, and simmer covered for 30 minutes.","Lift out the chicken, finish the sauce with cream and cold butter, and add the tarragon off the heat."]} },

{ id:'gratin-de-cardons', c:'eu', lat:45.750, lon:4.850, base:6, prep:60, cook:45, diff:2, tags:['veg','bake','festive'],
  art:{v:'plate',bg:'#2f3326',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#e8dcc0','#e0b45a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Cardons à la moelle',en:'Cardoons with marrow'},
  p:{fr:'Lyon, France',en:'Lyon, France'},
  d:{fr:"Des côtes de cardon longuement blanchies, gratinées sous une sauce à la moelle de bœuf. C'est le légume de Noël à Lyon : il ne se trouve qu'en décembre, et il faut trois heures pour l'apprivoiser.",
     en:"Cardoon ribs long-blanched and gratinated under a beef marrow sauce. It is the Christmas vegetable in Lyon: found only in December, and it takes three hours to tame."},
  i:[['cardoon',2,'kg'],['bone_marrow',300,'g'],['flour',60,'g'],['butter',80,'g'],['beef_stock',600,'ml'],['heavy_cream',200,'ml'],['gruyere_cheese',150,'g'],['lemon',2,'pc'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Effilez les côtes de cardon comme du céleri, en retirant tous les fils, et jetez-les au fur et à mesure dans une eau citronnée : à l'air, ils noircissent en une minute.","Faites-les cuire 1 h 30 dans un blanc — eau, farine délayée et citron — qui les garde pâles.","Faites dégorger la moelle 2 heures à l'eau glacée, puis pochez-la 10 minutes et coupez-la en rondelles.","Faites un roux, mouillez du fond de bœuf, laissez cuire 15 minutes et crémez.","Rangez les cardons égouttés dans un plat, disposez la moelle, nappez, parsemez de gruyère et gratinez 30 minutes à 200 °C."],
     en:["String the cardoon ribs like celery, removing every fibre, and drop them straight into acidulated water: in the air they blacken within a minute.","Cook them for 1½ hours in a blanc — water, slaked flour and lemon — which keeps them pale.","Soak the marrow for 2 hours in iced water, then poach it for 10 minutes and cut it into rounds.","Make a roux, moisten with beef stock, cook for 15 minutes and add cream.","Lay the drained cardoons in a dish, arrange the marrow, coat with sauce, scatter gruyère and gratinate for 30 minutes at 200°C."]} },

{ id:'poulet-gaston-gerard', c:'eu', lat:47.322, lon:5.041, base:4, prep:20, cook:50, diff:2, tags:['poultry','cheese','sunday'],
  art:{v:'pot',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#e0b45a','#f0e8d0','#c9924a','#e8dcc0'],garnish:'#7fae6a'},
  n:{fr:'Poulet Gaston Gérard',en:'Poulet Gaston Gérard'},
  p:{fr:'Dijon, Bourgogne, France',en:'Dijon, Burgundy, France'},
  d:{fr:"Un poulet à la crème, à la moutarde et au comté, gratiné à la chapelure. Né d'un accident en 1930 : l'épouse du maire de Dijon renversa du paprika dans la casserole et rattrapa le tout au fromage devant Curnonsky.",
     en:"Chicken with cream, mustard and comté, gratinated with breadcrumbs. Born of an accident in 1930: the Dijon mayor's wife spilt paprika into the pan and rescued it with cheese in front of Curnonsky."},
  i:[['chicken',1.6,'kg'],['dijon_mustard',4,'tbsp'],['heavy_cream',400,'ml'],['comte_cheese',200,'g'],['paprika',2,'tsp'],['white_wine',200,'ml'],['breadcrumbs',60,'g'],['butter',80,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez le poulet et faites-le colorer au beurre, peau vers le bas d'abord, dans une cocotte allant au four.","Saupoudrez de paprika, couvrez et laissez cuire 30 minutes à feu doux.","Retirez le poulet, déglacez au vin blanc et laissez réduire de moitié.","Ajoutez la crème et la moutarde hors du feu — bouillie, la moutarde devient amère — puis la moitié du comté.","Remettez le poulet, nappez, parsemez du reste de fromage et de chapelure, et gratinez 15 minutes à 220 °C."],
     en:["Joint the chicken and colour it in butter, skin down first, in an ovenproof pot.","Dust with paprika, cover and cook for 30 minutes over low heat.","Lift out the chicken, deglaze with white wine and reduce by half.","Add the cream and mustard off the heat — boiled, mustard turns bitter — then half the comté.","Return the chicken, coat it, scatter the remaining cheese and the breadcrumbs, and gratinate for 15 minutes at 220°C."]} },

{ id:'gougeres-au-jambon-persille', c:'eu', lat:47.797, lon:3.573, base:6, prep:35, cook:90, diff:2, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f5a3a','#c9754a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Rigodon bourguignon',en:'Burgundian rigodon'},
  p:{fr:'Auxerre, Bourgogne, France',en:'Auxerre, Burgundy, France'},
  d:{fr:"Un flan de brioche rassise, de lait et de noix, cuit au four à pain après la fournée. Il se fait salé, aux lardons, ou sucré selon les villages : la Bourgogne ne s'est jamais mise d'accord.",
     en:"A pudding of stale brioche, milk and walnuts, baked in the bread oven after the batch. It is made savoury with bacon or sweet depending on the village: Burgundy never agreed on it."},
  i:[['brioche',400,'g'],['whole_milk',700,'ml'],['egg',5,'pc'],['walnuts',150,'g'],['sugar',120,'g'],['butter',60,'g'],['cinnamon',1,'tsp'],['vanilla',1,'pc'],['red_currant_jelly',150,'g'],['salt',null,'']],
  s:{fr:["Taillez la brioche rassise en gros dés et rangez-la dans un plat beurré.","Portez le lait à frémissement avec la vanille fendue et la cannelle, et laissez infuser 15 minutes hors du feu.","Battez les œufs et le sucre, versez le lait chaud en filet en fouettant, sans faire d'omelette.","Versez sur la brioche et laissez-la boire 30 minutes : elle doit être complètement imbibée avant d'aller au four.","Parsemez de noix concassées et enfournez 50 minutes à 170 °C au bain-marie. Servez tiède avec de la gelée de groseille."],
     en:["Cut the stale brioche into large cubes and pack them into a buttered dish.","Bring the milk to a bare simmer with the split vanilla and cinnamon, and infuse off the heat for 15 minutes.","Beat the eggs and sugar, pour in the hot milk in a thin stream while whisking, without scrambling them.","Pour over the brioche and let it drink for 30 minutes: it must be thoroughly soaked before it goes in the oven.","Scatter crushed walnuts and bake for 50 minutes at 170°C in a water bath. Serve warm with redcurrant jelly."]} },

{ id:'saupiquet-morvandiau', c:'eu', lat:47.230, lon:3.980, base:4, prep:25, cook:35, diff:2, tags:['pork','comfort','sunday'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#f0d8c0','#e8dcc0','#c9754a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Saupiquet du Morvan',en:'Morvan saupiquet'},
  p:{fr:'Château-Chinon, Morvan, France',en:'Château-Chinon, Morvan, France'},
  d:{fr:"Des tranches de jambon du Morvan nappées d'une sauce à la crème, au genièvre et au vinaigre. Saupiquet vient de « sel qui pique » : la sauce médiévale était acide, et elle l'est restée.",
     en:"Slices of Morvan ham under a sauce of cream, juniper and vinegar. Saupiquet comes from 'salt that stings': the medieval sauce was sharp, and it has stayed so."},
  i:[['ham',8,'slice'],['shallot',4,'pc'],['red_wine_vinegar',80,'ml'],['white_wine',150,'ml'],['heavy_cream',300,'ml'],['juniper_berries',10,'pc'],['butter',80,'g'],['flour',30,'g'],['beef_stock',200,'ml'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites suer les échalotes ciselées au beurre sans les colorer, avec les baies de genièvre écrasées.","Versez le vinaigre et laissez-le réduire presque à sec : l'odeur doit cesser de piquer le nez.","Ajoutez le vin, réduisez de moitié, puis singez d'une cuillerée de farine et mouillez du fond.","Laissez cuire 15 minutes à petit feu, passez au chinois en pressant, et montez à la crème.","Faites juste tiédir les tranches de jambon dans la sauce, sans les laisser bouillir, et servez sur des pommes vapeur."],
     en:["Sweat the chopped shallots in butter without colouring, with the crushed juniper berries.","Add the vinegar and reduce it almost to nothing: the smell should stop catching the nose.","Add the wine, reduce by half, then dust in a spoonful of flour and moisten with the stock.","Cook gently for 15 minutes, strain through a fine sieve pressing well, and finish with cream.","Warm the ham slices through in the sauce without letting them boil, and serve with steamed potatoes."]} },

{ id:'pounti-auvergnat', c:'eu', lat:44.926, lon:2.443, base:6, prep:30, cook:60, diff:2, tags:['pork','bake','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ead4',style:'cake',food:['#7fae5a','#8f5a3a','#e8dcc0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Pounti',en:'Pounti'},
  p:{fr:'Aurillac, Cantal, France',en:'Aurillac, Cantal, France'},
  d:{fr:"Un pain de viande aux blettes et aux pruneaux, à mi-chemin du salé et du sucré. L'Auvergne le sert tiède en entrée ou froid en tranches : c'est le plat qui accompagne les moissons depuis toujours.",
     en:"A meat loaf with chard and prunes, halfway between savoury and sweet. Auvergne serves it warm as a starter or cold in slices: the harvest dish, always."},
  i:[['ground_pork',300,'g'],['smoked_bacon',200,'g'],['swiss_chard',400,'g'],['prunes',200,'g'],['onion',2,'pc'],['parsley',1,'bunch'],['flour',150,'g'],['egg',4,'pc'],['whole_milk',300,'ml'],['butter',40,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les pruneaux dans du thé tiède pendant que vous préparez le reste.","Hachez grossièrement les blettes, l'oignon, le persil, le lard et le porc — au couteau, pour garder du grain.","Faites une pâte lisse avec la farine, les œufs et le lait, puis incorporez le hachis.","Versez la moitié dans un moule beurré, disposez les pruneaux dénoyautés, et couvrez du reste.","Enfournez 55 minutes à 180 °C. Le pounti se démoule tiède et se coupe froid, plus proprement."],
     en:["Soak the prunes in warm tea while you prepare everything else.","Roughly chop the chard, onion, parsley, bacon and pork — by knife, to keep some texture.","Make a smooth batter with the flour, eggs and milk, then fold in the chopped mixture.","Pour half into a buttered tin, arrange the stoned prunes, and cover with the rest.","Bake for 55 minutes at 180°C. The pounti turns out warm and slices more cleanly cold."]} },

{ id:'chou-farci-auvergnat', c:'eu', lat:45.777, lon:3.087, base:6, prep:50, cook:150, diff:2, tags:['pork','slow','comfort'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#7fae5a','#4f6f3a','#8f5a3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Chou farci',en:'Stuffed cabbage'},
  p:{fr:'Clermont-Ferrand, Auvergne, France',en:'Clermont-Ferrand, Auvergne, France'},
  d:{fr:"Un chou entier reconstitué feuille à feuille autour d'une farce, ficelé et braisé trois heures. On ne le hache pas : on le remonte, feuille après feuille, jusqu'à retrouver la forme du chou d'origine.",
     en:"A whole cabbage rebuilt leaf by leaf around a stuffing, tied and braised for three hours. It is not chopped: it is reassembled, leaf after leaf, until the original cabbage takes shape again."},
  i:[['cabbage',1,'pc'],['ground_pork',500,'g'],['smoked_bacon',200,'g'],['stale_bread',150,'g'],['whole_milk',200,'ml'],['onion',2,'pc'],['garlic',4,'clove'],['egg',2,'pc'],['parsley',4,'tbsp'],['carrot',3,'pc'],['white_wine',250,'ml'],['chicken_broth',500,'ml'],['thyme',3,'sprig'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Blanchissez le chou entier 10 minutes, rafraîchissez-le et détachez délicatement les feuilles une à une, en les gardant dans l'ordre.","Retirez les côtes les plus épaisses au couteau, sans percer la feuille.","Mêlez le porc, le lard, la mie trempée pressée, l'oignon fondu, l'ail, les œufs et le persil.","Dans un linge, reformez le chou : les grandes feuilles au fond, puis une couche de farce, des feuilles, de la farce, jusqu'au cœur.","Ficelez le linge, posez le chou sur un lit de carottes, mouillez de vin et de bouillon, et braisez 2 h 30 à 160 °C."],
     en:["Blanch the whole cabbage for 10 minutes, refresh it and peel the leaves off one by one, keeping them in order.","Pare away the thickest ribs with a knife, without piercing the leaf.","Mix the pork, bacon, squeezed soaked bread, softened onion, garlic, eggs and parsley.","In a cloth, rebuild the cabbage: the largest leaves at the bottom, then a layer of stuffing, leaves, stuffing, up to the heart.","Tie the cloth, set the cabbage on a bed of carrots, add wine and stock, and braise for 2½ hours at 160°C."]} },

{ id:'sanciau-bourbonnais', c:'eu', lat:46.566, lon:3.335, base:4, prep:15, cook:20, diff:1, tags:['veg','fast','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#c9924a','#f0e8d0','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Sanciau',en:'Sanciau'},
  p:{fr:'Moulins, Bourbonnais, France',en:'Moulins, Bourbonnais, France'},
  d:{fr:"Une crêpe épaisse à la farine de blé et de sarrasin, cuite au saindoux, servie salée ou saupoudrée de sucre. C'était le repas du soir dans le Bourbonnais pauvre : de la farine, un œuf, et ce qui restait de lait.",
     en:"A thick pancake of wheat and buckwheat flour, cooked in lard, served savoury or dusted with sugar. It was supper in poor Bourbonnais: flour, an egg, and whatever milk was left."},
  i:[['flour',200,'g'],['buckwheat_flour',100,'g'],['egg',3,'pc'],['whole_milk',500,'ml'],['lard',80,'g'],['sugar',60,'g'],['smoked_bacon',150,'g'],['apple',2,'pc'],['salt',null,'']],
  s:{fr:["Mêlez les deux farines et le sel, creusez un puits, cassez-y les œufs et délayez au lait, sans grumeau.","Laissez reposer une heure : la pâte doit rester épaisse, plus proche d'une pâte à blinis que d'une pâte à crêpes.","Faites fondre une bonne cuillerée de saindoux dans une poêle de fonte, jusqu'à ce qu'elle fume légèrement.","Versez une louche épaisse et laissez prendre 6 minutes sans y toucher : le sanciau se retourne d'un coup, à la poêle.","Servez-le salé avec des lardons rissolés, ou sucré avec des pommes poêlées."],
     en:["Mix the two flours and the salt, make a well, break in the eggs and slacken with milk, lump-free.","Rest for an hour: the batter should stay thick, closer to blini batter than to crêpe batter.","Melt a good spoonful of lard in a cast-iron pan, until it just smokes.","Pour in a thick ladleful and let it set for 6 minutes untouched: the sanciau is flipped in one movement.","Serve it savoury with fried bacon, or sweet with pan-fried apples."]} },

{ id:'clafoutis-limousin', c:'eu', lat:45.833, lon:1.262, base:6, prep:15, cook:40, diff:1, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#2c2434',plate:'#f4ead4',style:'cake',food:['#f2dfa8','#8f1a3a','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Clafoutis',en:'Clafoutis'},
  p:{fr:'Limoges, Limousin, France',en:'Limoges, Limousin, France'},
  d:{fr:"Un flan de cerises noires cuit au four, dont on ne dénoyaute surtout pas les fruits. Le noyau parfume la crème d'une note d'amande pendant la cuisson : le retirer, en Limousin, c'est faire autre chose.",
     en:"A baked black cherry custard whose fruit is emphatically not stoned. The stone perfumes the custard with almond as it bakes: removing it, in Limousin, is making something else."},
  i:[['black_cherries',700,'g'],['flour',120,'g'],['sugar',150,'g'],['egg',4,'pc'],['whole_milk',400,'ml'],['heavy_cream',100,'ml'],['butter',40,'g'],['vanilla',1,'pc'],['brandy',2,'tbsp'],['salt',null,'']],
  s:{fr:["Lavez et équeutez les cerises sans les dénoyauter, et laissez-les macérer 30 minutes au sucre et à l'eau-de-vie.","Beurrez généreusement un plat de terre et sucrez-le : la croûte caramélisée des bords en dépend.","Fouettez les œufs et le sucre, ajoutez la farine, puis le lait et la crème en filet, et la vanille grattée.","Rangez les cerises serrées au fond du plat et versez l'appareil par-dessus.","Enfournez 40 minutes à 180 °C. Servez tiède, jamais froid, et prévenez vos convives pour les noyaux."],
     en:["Wash and stem the cherries without stoning them, and macerate them for 30 minutes in sugar and brandy.","Butter an earthenware dish generously and sugar it: the caramelised rim depends on it.","Whisk the eggs and sugar, add the flour, then the milk and cream in a thin stream, and the scraped vanilla.","Pack the cherries tightly over the base and pour the batter over them.","Bake for 40 minutes at 180°C. Serve warm, never cold, and warn your guests about the stones."]} },

{ id:'poulet-basquaise', c:'eu', lat:43.483, lon:-1.558, base:6, prep:30, cook:60, diff:1, tags:['poultry','comfort','sunday'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#c9402c','#e0913a','#4f8f4a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Poulet basquaise',en:'Basque chicken'},
  p:{fr:'Bayonne, Pays basque, France',en:'Bayonne, Basque Country, France'},
  d:{fr:"Du poulet mijoté dans une piperade de poivrons doux, de tomates et de piment d'Espelette. Le poivron doit fondre une heure avant que la volaille n'entre : c'est lui le plat, la viande n'est qu'invitée.",
     en:"Chicken stewed in a piperade of sweet peppers, tomatoes and Espelette chilli. The peppers must melt for an hour before the bird goes in: they are the dish, the meat is merely invited."},
  i:[['chicken',1.8,'kg'],['red_pepper',4,'pc'],['green_pepper',2,'pc'],['ripe_tomato',800,'g'],['onion',3,'pc'],['garlic',6,'clove'],['bayonne_ham',150,'g'],['espelette_pepper',2,'tsp'],['white_wine',200,'ml'],['olive_oil',100,'ml'],['thyme',3,'sprig'],['long_grain_rice',400,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites colorer le poulet découpé dans l'huile d'olive, puis réservez-le.","Faites fondre l'oignon, les poivrons en lanières et l'ail dans la même huile, à couvert, 40 minutes.","Ajoutez la tomate pelée et concassée et laissez réduire encore 20 minutes : la piperade doit épaissir, pas baigner.","Déglacez au vin blanc, ajoutez le piment d'Espelette et le jambon de Bayonne en dés.","Remettez le poulet, couvrez et laissez mijoter 35 minutes. Servez avec du riz blanc."],
     en:["Colour the jointed chicken in olive oil, then set it aside.","Soften the onion, peppers in strips and garlic in the same oil, covered, for 40 minutes.","Add the peeled crushed tomatoes and reduce for another 20 minutes: the piperade should thicken, not swim.","Deglaze with white wine, add the Espelette chilli and the diced Bayonne ham.","Return the chicken, cover and simmer for 35 minutes. Serve with white rice."]} },

{ id:'chipirons-a-l-encre', c:'eu', lat:43.388, lon:-1.663, base:4, prep:40, cook:50, diff:3, tags:['sea','comfort','slow'],
  art:{v:'pot',bg:'#1e2028',plate:'#f4ecd8',style:'stew',food:['#2a2a2a','#3a3a3a','#e0913a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Chipirons à l’encre',en:'Squid in their ink'},
  p:{fr:'Saint-Jean-de-Luz, Pays basque, France',en:'Saint-Jean-de-Luz, Basque Country, France'},
  d:{fr:"De petits calmars mijotés dans une sauce noire faite de leur propre encre. On les farcit de leurs tentacules hachés : rien ne se jette, et la couleur d'encre effraie autant qu'elle attire.",
     en:"Small squid stewed in a black sauce made from their own ink. They are stuffed with their chopped tentacles: nothing is wasted, and the ink colour frightens as much as it draws."},
  i:[['squid',1.2,'kg'],['squid_ink',4,'pc'],['onion',4,'pc'],['green_pepper',2,'pc'],['ripe_tomato',400,'g'],['garlic',6,'clove'],['white_wine',200,'ml'],['stale_bread',60,'g'],['olive_oil',100,'ml'],['parsley',4,'tbsp'],['long_grain_rice',300,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Videz les calmars en gardant les poches d'encre intactes dans un bol : percées trop tôt, elles se perdent.","Hachez les tentacules avec un peu d'ail et de persil, et farcissez-en les corps, refermés d'un cure-dent.","Faites fondre longuement oignon, poivron et ail dans l'huile — 40 minutes à couvert — jusqu'à obtenir une confiture.","Ajoutez la tomate, le vin, la mie de pain et l'encre délayée dans un peu d'eau, puis mixez et passez au tamis.","Pochez les chipirons 25 minutes dans cette sauce noire, à tout petit feu : bouillis, ils deviennent caoutchouc."],
     en:["Clean the squid keeping the ink sacs intact in a bowl: burst too early, they are lost.","Chop the tentacles with a little garlic and parsley, and stuff the bodies with them, closed with a cocktail stick.","Soften the onion, pepper and garlic at length in the oil — 40 minutes covered — until jammy.","Add the tomato, wine, breadcrumb and the ink slaked in a little water, then blend and pass through a sieve.","Poach the squid for 25 minutes in this black sauce, over the gentlest heat: boiled, they turn to rubber."]} },

{ id:'aligot-saucisse-de-toulouse', c:'eu', lat:43.605, lon:1.444, base:6, prep:20, cook:40, diff:2, tags:['pork','grill','comfort'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'grill',food:['#8f5a3a','#c9754a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Saucisse de Toulouse aux haricots',en:'Toulouse sausage with beans'},
  p:{fr:'Toulouse, Occitanie, France',en:'Toulouse, Occitanie, France'},
  d:{fr:"La saucisse en spirale, piquée et grillée doucement, sur un lit de haricots à la graisse d'oie. On ne la coupe jamais avant cuisson : elle se saisit entière, enroulée sur elle-même, et se partage à table.",
     en:"The coiled sausage, pricked and grilled slowly, on a bed of beans in goose fat. It is never cut before cooking: it is seared whole, coiled on itself, and shared at the table."},
  i:[['toulouse_sausage',1,'kg'],['white_beans',500,'g'],['duck_fat',80,'g'],['onion',2,'pc'],['carrot',2,'pc'],['garlic',6,'clove'],['ripe_tomato',300,'g'],['bay_leaf',2,'pc'],['thyme',3,'sprig'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots une nuit, puis cuisez-les 1 heure avec la carotte, l'oignon piqué et le laurier.","Piquez la saucisse d'une aiguille en une dizaine d'endroits : sans cela, elle éclate et perd tout son jus.","Faites-la cuire à la graisse d'oie 25 minutes à feu très doux, en la retournant à mi-parcours avec deux spatules.","Faites revenir l'ail et la tomate dans la graisse rendue, ajoutez les haricots égouttés et laissez confire 15 minutes.","Servez la spirale entière posée sur les haricots, avec du persil, et découpez devant les convives."],
     en:["Soak the beans overnight, then cook them for 1 hour with the carrot, clove-studded onion and bay.","Prick the sausage with a needle in a dozen places: without this it bursts and loses all its juice.","Cook it in goose fat for 25 minutes over very low heat, turning it halfway with two spatulas.","Fry the garlic and tomato in the rendered fat, add the drained beans and stew for 15 minutes.","Serve the whole coil set on the beans, with parsley, and cut it in front of your guests."]} },

{ id:'brouillade-aux-truffes', c:'eu', lat:44.135, lon:5.146, base:4, prep:15, cook:20, diff:2, tags:['veg','festive','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#e8c46a','#f0e8d0','#3a2a1a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Brouillade aux truffes',en:'Truffle brouillade'},
  p:{fr:'Carpentras, Vaucluse, France',en:'Carpentras, Vaucluse, France'},
  d:{fr:"Des œufs brouillés au bain-marie, parfumés par une truffe noire enfermée avec eux la veille. La coquille est poreuse : l'œuf prend le parfum sans qu'on l'ouvre, et c'est là le vrai secret du plat.",
     en:"Eggs scrambled over a water bath, perfumed by a black truffle shut in with them the day before. The shell is porous: the egg takes the scent without being cracked, and that is the real secret."},
  i:[['egg',10,'pc'],['black_truffle',40,'g'],['butter',80,'g'],['heavy_cream',60,'ml'],['olive_oil',2,'tbsp'],['white_bread',4,'slice'],['salt',null,''],['pepper',null,'']],
  s:{fr:["La veille, enfermez la truffe brossée et les œufs entiers dans une boîte hermétique, au frais.","Le jour même, battez les œufs à peine, sans les monter : une brouillade se fait à la fourchette, pas au fouet.","Cuisez-les au bain-marie frémissant en remuant sans arrêt à la spatule, 15 minutes durant.","Retirez du feu quand ils sont encore trop coulants : la chaleur résiduelle finit le travail.","Incorporez le beurre froid, la crème et la truffe râpée hors du feu, et servez aussitôt sur du pain grillé."],
     en:["The day before, shut the brushed truffle and the whole eggs in an airtight box in the cold.","On the day, beat the eggs barely, without aerating them: a brouillade is made with a fork, not a whisk.","Cook them over a simmering water bath, stirring constantly with a spatula, for a full 15 minutes.","Take them off the heat while still too runny: residual warmth finishes the job.","Fold in the cold butter, cream and grated truffle off the heat, and serve at once on toast."]} },

{ id:'grand-aioli', c:'eu', lat:43.529, lon:5.445, base:8, prep:45, cook:40, diff:2, tags:['sea','veg','sunday'],
  art:{v:'board',bg:'#28331f',plate:'#f4ecd8',style:'fish',food:['#f4f0e6','#e0b45a','#7fae5a','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Grand aïoli',en:'Grand aïoli'},
  p:{fr:'Aix-en-Provence, Provence, France',en:'Aix-en-Provence, Provence, France'},
  d:{fr:"De la morue pochée et tous les légumes du jardin autour d'un mortier d'aïoli. C'est le repas du vendredi provençal, et le plat entier tire son nom de la sauce : sans elle, ce n'est qu'un plateau de légumes.",
     en:"Poached salt cod and every vegetable from the garden around a mortar of aïoli. It is the Provençal Friday meal, and the whole dish takes its name from the sauce: without it, it is just a vegetable platter."},
  i:[['salt_cod',1,'kg'],['garlic',12,'clove'],['egg_yolk',3,'pc'],['olive_oil',500,'ml'],['potato',800,'g'],['carrot',6,'pc'],['green_beans',400,'g'],['cauliflower',1,'pc'],['beetroot',4,'pc'],['egg',6,'pc'],['snails',24,'pc'],['lemon',2,'pc'],['salt',null,'']],
  s:{fr:["Faites dessaler la morue 24 heures à l'eau froide, en changeant l'eau cinq fois.","Pilez l'ail dégermé avec une pincée de gros sel jusqu'à obtenir une crème parfaitement lisse : le mortier n'est pas négociable.","Ajoutez les jaunes, puis l'huile d'olive goutte à goutte d'abord, en tournant toujours dans le même sens.","Si la sauce tourne, repartez d'un jaune neuf et incorporez-y la sauce ratée cuillère par cuillère.","Pochez la morue 10 minutes sans bouillir, cuisez chaque légume séparément, et dressez le tout autour du mortier."],
     en:["Soak the salt cod for 24 hours in cold water, changing the water five times.","Pound the degermed garlic with a pinch of coarse salt into a perfectly smooth cream: the mortar is not negotiable.","Add the yolks, then the olive oil drop by drop at first, always turning the same way.","If the sauce splits, start again with a fresh yolk and beat the failed sauce into it a spoonful at a time.","Poach the cod for 10 minutes without boiling, cook each vegetable separately, and arrange everything around the mortar."]} },

{ id:'boles-de-picolat', c:'eu', lat:42.699, lon:2.895, base:6, prep:40, cook:75, diff:2, tags:['pork','comfort','slow'],
  art:{v:'pot',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#8f5a3a','#c9402c','#4f6f3a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Boles de picolat',en:'Boles de picolat'},
  p:{fr:'Perpignan, Roussillon, France',en:'Perpignan, Roussillon, France'},
  d:{fr:"Des boulettes de porc et de bœuf mijotées avec des olives vertes et des cèpes, à la catalane. Le plat du dimanche en Roussillon ; il se réchauffe le lundi et tout le monde s'accorde à le trouver meilleur.",
     en:"Pork and beef meatballs stewed with green olives and ceps, Catalan style. The Sunday dish of Roussillon; reheated on Monday, and everyone agrees it is better then."},
  i:[['ground_pork',400,'g'],['ground_beef',300,'g'],['stale_bread',100,'g'],['whole_milk',150,'ml'],['egg',2,'pc'],['garlic',8,'clove'],['parsley',4,'tbsp'],['flour',60,'g'],['onion',3,'pc'],['ripe_tomato',600,'g'],['green_olives',200,'g'],['dried_porcini',40,'g'],['lard',60,'g'],['white_wine',150,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Trempez la mie dans le lait, pressez-la, et mêlez-la aux viandes, aux œufs, à l'ail et au persil. Laissez reposer une heure au frais.","Formez des boulettes de la taille d'une noix, farinez-les et faites-les dorer au saindoux, sans les remuer trop tôt.","Faites fondre les oignons dans la même graisse, ajoutez la tomate et le vin blanc.","Ajoutez les cèpes trempés et leur eau filtrée, puis remettez les boulettes.","Laissez mijoter 45 minutes, ajoutez les olives dessalées pour les 15 dernières minutes."],
     en:["Soak the breadcrumb in milk, squeeze it, and mix it with the meats, eggs, garlic and parsley. Rest for an hour in the cold.","Roll walnut-sized balls, flour them and brown them in lard, without stirring too soon.","Soften the onions in the same fat, add the tomato and the white wine.","Add the soaked ceps and their strained liquor, then return the meatballs.","Simmer for 45 minutes, adding the desalted olives for the last 15."]} },

{ id:'anchoiade-collioure', c:'eu', lat:42.526, lon:3.083, base:6, prep:20, cook:5, diff:1, tags:['sea','fast','fresh'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'salad',food:['#8f5a3a','#e0b45a','#7fae5a','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Anchoïade de Collioure',en:'Collioure anchoïade'},
  p:{fr:'Collioure, Roussillon, France',en:'Collioure, Roussillon, France'},
  d:{fr:"Une pâte d'anchois salés, d'ail et d'huile d'olive, servie tiède avec des légumes crus. Collioure sale ses anchois depuis le Moyen Âge ; on les rince mais on ne les dessale jamais complètement.",
     en:"A paste of salted anchovies, garlic and olive oil, served warm with raw vegetables. Collioure has salted anchovies since the Middle Ages; they are rinsed but never fully desalted."},
  i:[['anchovy_fillets',250,'g'],['garlic',8,'clove'],['olive_oil',200,'ml'],['red_wine_vinegar',2,'tbsp'],['almonds',60,'g'],['thyme',2,'sprig'],['celery',6,'stalk'],['radish',2,'bunch'],['fennel',2,'pc'],['rustic_bread',1,'pc'],['pepper',null,'']],
  s:{fr:["Rincez les anchois salés à l'eau claire et épongez-les, mais ne les faites pas tremper : ils perdraient leur caractère.","Pilez-les au mortier avec l'ail dégermé et les amandes mondées, jusqu'à obtenir une pâte grossière.","Incorporez l'huile d'olive en filet, comme pour une mayonnaise, puis le vinaigre et le thym effeuillé.","Faites tiédir la sauce au bain-marie sans jamais la faire frémir : chauffée, elle se sépare.","Servez dans le mortier, avec céleri, radis, fenouil crus et de larges tranches de pain de campagne."],
     en:["Rinse the salted anchovies in clean water and pat them dry, but do not soak them: they would lose their character.","Pound them in a mortar with the degermed garlic and blanched almonds, into a coarse paste.","Work in the olive oil in a thin stream, as for a mayonnaise, then the vinegar and picked thyme.","Warm the sauce over a water bath without ever letting it tremble: heated, it splits.","Serve in the mortar, with raw celery, radishes, fennel and thick slices of country bread."]} },

{ id:'tourte-aux-herbes-nicoise', c:'eu', lat:43.700, lon:7.268, base:6, prep:50, cook:45, diff:2, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ead4',style:'cake',food:['#4f6f3a','#7fae5a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tourte de courge niçoise',en:'Niçois squash tart'},
  p:{fr:'Nice, Côte d’Azur, France',en:'Nice, Côte d’Azur, France'},
  d:{fr:"Une tourte de courge longue de Nice, de riz et de parmesan, dorée à l'huile d'olive. Elle se mange froide, coupée en carrés, et se transporte : c'était le repas des ouvriers du port.",
     en:"A tart of long Nice squash, rice and parmesan, glazed with olive oil. It is eaten cold, cut into squares, and travels well: it was the dockworkers' lunch."},
  i:[['flour',400,'g'],['olive_oil',150,'ml'],['warm_water',150,'ml'],['pumpkin',1.2,'kg'],['long_grain_rice',120,'g'],['onion',3,'pc'],['parmesan',150,'g'],['egg',3,'pc'],['basil',1,'bunch'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine, l'huile d'olive, l'eau tiède et le sel en une pâte souple ; laissez-la reposer une heure.","Râpez la courge grossièrement, salez-la et laissez-la dégorger 30 minutes, puis pressez-la à fond entre les mains.","Faites fondre l'oignon à l'huile, cuisez le riz à moitié, et laissez tiédir l'un et l'autre.","Mêlez courge pressée, riz, oignon, parmesan, œufs, basilic ciselé et muscade.","Chemisez un moule de pâte fine, garnissez, couvrez d'un second disque, huilez le dessus et enfournez 45 minutes à 190 °C."],
     en:["Knead the flour, olive oil, warm water and salt into a supple dough; rest it for an hour.","Coarsely grate the squash, salt it and let it drain for 30 minutes, then squeeze it hard between your hands.","Soften the onion in oil, cook the rice halfway, and let both cool.","Mix the squeezed squash, rice, onion, parmesan, eggs, chopped basil and nutmeg.","Line a tin with thin pastry, fill it, cover with a second disc, oil the top and bake for 45 minutes at 190°C."]} },

{ id:'sardines-farcies-provencales', c:'eu', lat:43.297, lon:5.377, base:4, prep:35, cook:20, diff:2, tags:['sea','bake','fresh'],
  art:{v:'plate',bg:'#26384a',plate:'#f4ecd8',style:'fish',food:['#c9c0b0','#7fae5a','#e0b45a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Sardines farcies',en:'Stuffed sardines'},
  p:{fr:'Marseille, Provence, France',en:'Marseille, Provence, France'},
  d:{fr:"Des sardines ouvertes à plat, garnies d'épinards et de parmesan, rangées serrées dans un plat. On les ouvre au pouce, sans couteau : le poisson se sépare tout seul le long de l'arête si on le fait bien.",
     en:"Sardines opened flat, filled with spinach and parmesan, packed tightly in a dish. They are opened with the thumb, not a knife: the fish parts along the bone by itself if you do it right."},
  i:[['sardines',1.2,'kg'],['spinach',600,'g'],['stale_bread',100,'g'],['whole_milk',100,'ml'],['parmesan',100,'g'],['egg',2,'pc'],['garlic',4,'clove'],['parsley',4,'tbsp'],['olive_oil',80,'ml'],['lemon',2,'pc'],['breadcrumbs',40,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Écaillez les sardines, ouvrez-les au pouce depuis le ventre et retirez l'arête centrale en tirant vers la queue.","Faites tomber les épinards, essorez-les très fort et hachez-les.","Mêlez-les à la mie trempée pressée, au parmesan, aux œufs, à l'ail et au persil.","Garnissez la moitié des sardines, couvrez chacune d'une seconde, chair contre chair, et rangez-les serrées.","Arrosez d'huile d'olive, parsemez de chapelure et enfournez 18 minutes à 200 °C. Servez tiède au citron."],
     en:["Scale the sardines, open them from the belly with your thumb and pull the backbone out towards the tail.","Wilt the spinach, squeeze it very dry and chop it.","Mix it with the squeezed soaked bread, parmesan, eggs, garlic and parsley.","Fill half the sardines, cover each with a second one flesh to flesh, and pack them tightly.","Drizzle with olive oil, scatter breadcrumbs and bake for 18 minutes at 200°C. Serve warm with lemon."]} },

{ id:'omelette-de-la-mere-poulard', c:'eu', lat:48.636, lon:-1.511, base:2, prep:10, cook:10, diff:3, tags:['veg','fast','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'cake',food:['#f2dfa8','#e0b45a','#f0e8d0','#e8dcc0'],garnish:'#7fae6a'},
  n:{fr:'Omelette de la Mère Poulard',en:'Mère Poulard omelette'},
  p:{fr:'Le Mont-Saint-Michel, Normandie, France',en:'Mont-Saint-Michel, Normandy, France'},
  d:{fr:"Une omelette battue vingt minutes au fouet et cuite sur feu de bois dans une poêle à long manche. Annette Poulard nourrissait ainsi les pèlerins dès 1888 ; elle a toujours refusé de livrer sa recette, disant qu'il n'y en avait pas.",
     en:"An omelette beaten for twenty minutes and cooked over a wood fire in a long-handled pan. Annette Poulard fed pilgrims this way from 1888; she always refused to give the recipe, saying there wasn't one."},
  i:[['egg',6,'pc'],['butter',80,'g'],['heavy_cream',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Séparez les blancs des jaunes. Battez les jaunes avec la crème, le sel et le poivre.","Montez les blancs en neige très ferme, longuement — c'est là qu'est le secret, et il n'y en a pas d'autre.","Incorporez délicatement les jaunes aux blancs, en soulevant la masse, sans jamais tourner.","Faites mousser une grosse noix de beurre dans une poêle brûlante et versez l'appareil d'un coup.","Laissez gonfler 5 minutes sans y toucher, pliez en deux et servez immédiatement : elle retombe en une minute."],
     en:["Separate the whites from the yolks. Beat the yolks with the cream, salt and pepper.","Whisk the whites to very stiff peaks, at length — that is the secret, and there is no other.","Fold the yolks gently into the whites, lifting the mass, never stirring.","Foam a large knob of butter in a scorching pan and pour in the mixture all at once.","Let it puff for 5 minutes untouched, fold it in two and serve immediately: it collapses within a minute."]} },

{ id:'douillons-normands', c:'eu', lat:49.427, lon:0.232, base:6, prep:35, cook:45, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#c9924a','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Douillons aux poires',en:'Pear douillons'},
  p:{fr:'Honfleur, Normandie, France',en:'Honfleur, Normandy, France'},
  d:{fr:"Des poires entières enfermées dans une pâte brisée et cuites au four, la queue dépassant. En Normandie, on les fait à la pomme comme au bourdelot ; à la poire, elles gardent une élégance que la pomme n'a pas.",
     en:"Whole pears sealed in shortcrust and baked, the stalk left poking out. In Normandy they are made with apple, as bourdelots; with pear they keep an elegance the apple lacks."},
  i:[['flour',400,'g'],['butter',220,'g'],['egg',2,'pc'],['sugar',120,'g'],['pear',6,'pc'],['ice_water',60,'ml'],['cinnamon',1,'tsp'],['red_currant_jelly',100,'g'],['calvados',3,'tbsp'],['heavy_cream',200,'ml'],['salt',null,'']],
  s:{fr:["Sablez la farine et le beurre froid, liez d'un jaune et d'eau glacée, et laissez reposer une heure au frais.","Pelez les poires en gardant la queue, évidez-les par-dessous à la cuillère à racine.","Garnissez le creux d'un mélange de beurre, de sucre, de cannelle et d'une goutte de calvados.","Étalez la pâte, découpez des disques, enveloppez chaque poire en remontant la pâte et en laissant sortir la queue.","Dorez à l'œuf et enfournez 40 minutes à 190 °C. Servez tiède avec de la crème et de la gelée de groseille."],
     en:["Rub the flour and cold butter together, bind with a yolk and iced water, and rest for an hour in the cold.","Peel the pears keeping the stalks, and core them from below with a corer.","Fill the hollow with a mixture of butter, sugar, cinnamon and a drop of calvados.","Roll out the pastry, cut discs, and wrap each pear by drawing the pastry up, leaving the stalk out.","Glaze with egg and bake for 40 minutes at 190°C. Serve warm with cream and redcurrant jelly."]} },

{ id:'lentilles-au-petit-sale', c:'eu', lat:45.043, lon:3.885, base:6, prep:20, cook:90, diff:1, tags:['pork','legume','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#4a4a3a','#8f5a3a','#e0b45a','#c9754a'],garnish:'#7fae6a'},
  n:{fr:'Lentilles vertes au petit salé',en:'Green lentils with salt pork'},
  p:{fr:'Le Puy-en-Velay, Haute-Loire, France',en:'Le Puy-en-Velay, Haute-Loire, France'},
  d:{fr:"Des lentilles vertes du Puy et du travers de porc salé, mijotés ensemble sans jamais bouillir. La lentille du Puy ne se fait pas tremper : sa peau est si fine qu'elle éclaterait, et elle doit rester entière.",
     en:"Green Puy lentils and salted pork ribs, simmered together and never boiled. Puy lentils are not soaked: the skin is so fine it would burst, and they must stay whole."},
  i:[['green_lentils',500,'g'],['salted_pork',800,'g'],['smoked_sausage',300,'g'],['carrot',3,'pc'],['onion',2,'pc'],['cloves',4,'pc'],['bay_leaf',2,'pc'],['thyme',3,'sprig'],['garlic',4,'clove'],['butter',40,'g'],['dijon_mustard',2,'tbsp'],['parsley',3,'tbsp'],['pepper',null,'']],
  s:{fr:["Faites dessaler le petit salé 4 heures à l'eau froide, puis blanchissez-le 10 minutes et jetez cette eau.","Rincez les lentilles sans les tremper et mettez-les dans une eau froide non salée : salées d'avance, elles restent dures.","Ajoutez l'oignon piqué de clous, la carotte, l'ail, le thym et le laurier, et portez à frémissement.","Ajoutez la viande et laissez cuire 45 minutes sans jamais bouillir : un bouillon franc ferait éclater les peaux.","Ajoutez la saucisse pour les 20 dernières minutes. Salez à la fin, beurrez et servez avec de la moutarde."],
     en:["Soak the salt pork for 4 hours in cold water, then blanch it for 10 minutes and discard that water.","Rinse the lentils without soaking and put them in cold unsalted water: salted in advance, they stay hard.","Add the clove-studded onion, carrot, garlic, thyme and bay, and bring to a bare simmer.","Add the meat and cook for 45 minutes without ever boiling: a rolling boil would split the skins.","Add the sausage for the last 20 minutes. Salt at the end, add butter and serve with mustard."]} }
,
{ id:'kouign-amann-malouin', c:'eu', lat:48.649, lon:-2.026, base:8, prep:180, cook:35, diff:3, tags:['sweet','bake','bread'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#c98a2c','#e0b45a','#f2dfa8','#8f5a3a'],garnish:'#c9754a'},
  n:{fr:'Kouign-amann malouin',en:'Saint-Malo kouign-amann'},
  p:{fr:'Saint-Malo, Ille-et-Vilaine, France',en:'Saint-Malo, Ille-et-Vilaine, France'},
  d:{fr:"La version individuelle du gâteau de Douarnenez, cuite en moule et non en grand disque. Saint-Malo l'a adoptée tard, au XXe siècle, et l'a taillée pour la main : les bords caramélisent davantage, ce qui est tout l'intérêt.",
     en:"The individual version of the Douarnenez cake, baked in a mould rather than as one large round. Saint-Malo adopted it late, in the 20th century, and cut it to fit the hand: the edges caramelise more, which is the whole point."},
  i:[['flour',500,'g'],['fresh_yeast',15,'g'],['warm_water',300,'ml'],['salted_butter',350,'g'],['sugar',300,'g'],['pearl_sugar',60,'g'],['salt',null,'']],
  s:{fr:["Pétrissez farine, levure délayée dans l'eau tiède et sel, sans aucun beurre, et laissez lever 1 h 30.","Étalez la pâte en rectangle, déposez le beurre demi-sel bien froid en plaque au centre, et enfermez-le comme une lettre.","Donnez trois tours simples en sucrant généreusement entre chaque, avec 20 minutes de repos au froid : le sucre doit rester en couche, jamais fondre dans la pâte.","Découpez des carrés de 10 cm, rabattez les quatre coins vers le centre et déposez-les dans des moules à muffin beurrés et sucrés.","Laissez pousser 45 minutes, parsemez de sucre perlé, et enfournez 35 minutes à 200 °C. Démoulez brûlant, sinon le caramel colle et le gâteau reste au fond."],
     en:["Knead the flour, yeast slaked in warm water and salt, with no butter at all, and prove for 1½ hours.","Roll the dough into a rectangle, lay the very cold salted butter as a slab in the centre, and enclose it like a letter.","Give three single turns, sugaring generously between each, with 20 minutes' rest in the cold: the sugar must stay in layers, never dissolve into the dough.","Cut 10 cm squares, fold the four corners to the centre and set them in buttered, sugared muffin moulds.","Prove for 45 minutes, scatter pearl sugar, and bake for 35 minutes at 200°C. Turn out while scalding, or the caramel sets and the cake stays in the tin."]} },

{ id:'moules-a-la-malouine', c:'eu', lat:48.652, lon:-2.026, base:4, prep:25, cook:20, diff:1, tags:['sea','fast','comfort'],
  art:{v:'pot',bg:'#26384a',plate:'#f4ecd8',style:'stew',food:['#3a3a4a','#f0e8d0','#e8dcc0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Moules à la malouine',en:'Saint-Malo mussels'},
  p:{fr:'Saint-Malo, Ille-et-Vilaine, France',en:'Saint-Malo, Ille-et-Vilaine, France'},
  d:{fr:"Des moules de bouchot ouvertes au cidre brut et liées à la crème, avec une pointe de curry. Le curry vient des armateurs malouins, qui rapportaient des Indes ce que la Bretagne n'avait pas : il se sent à peine, et il manque dès qu'on l'ôte.",
     en:"Bouchot mussels opened in dry cider and finished with cream, with a hint of curry. The curry came from Saint-Malo shipowners, who brought back from the Indies what Brittany lacked: it barely registers, and is missed the moment it is left out."},
  i:[['mussels',3,'kg'],['dry_cider',400,'ml'],['heavy_cream',250,'ml'],['shallot',6,'pc'],['curry_powder',1,'tsp'],['salted_butter',80,'g'],['parsley',4,'tbsp'],['bay_leaf',2,'pc'],['thyme',3,'sprig'],['potato',800,'g'],['pepper',null,'']],
  s:{fr:["Grattez les moules et retirez le byssus en tirant vers la charnière ; écartez toutes celles qui restent ouvertes après un coup sec.","Faites fondre les échalotes ciselées au beurre demi-sel, sans les colorer, avec le thym et le laurier.","Ajoutez le curry hors du feu — trente secondes de trop et il devient poudreux — puis versez le cidre et portez à ébullition.","Jetez les moules d'un coup, couvrez, et secouez la marmite deux fois : elles s'ouvrent en 4 minutes, pas davantage.","Retirez-les, faites réduire le jus de moitié, ajoutez la crème hors du feu, et reversez sur les moules. Ne salez jamais : la mer s'en est chargée."],
     en:["Scrub the mussels and pull the beard towards the hinge; discard any that stay open after a sharp tap.","Soften the chopped shallots in salted butter, without colouring, with the thyme and bay.","Add the curry off the heat — thirty seconds too long and it turns powdery — then pour in the cider and bring to the boil.","Tip in the mussels all at once, cover, and shake the pot twice: they open within 4 minutes, no longer.","Lift them out, reduce the liquor by half, add the cream off the heat, and pour it back over. Never salt: the sea has seen to that."]} },

{ id:'madeleines-au-beurre-bordier', c:'eu', lat:48.648, lon:-2.025, base:12, prep:30, cook:12, diff:2, tags:['sweet','bake','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f2dfa8','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Madeleines au beurre Bordier',en:'Madeleines with Bordier butter'},
  p:{fr:'Saint-Malo, Ille-et-Vilaine, France',en:'Saint-Malo, Ille-et-Vilaine, France'},
  d:{fr:"Des madeleines au beurre baratté de Saint-Malo, dont la bosse dépend d'un choc de température. Jean-Yves Bordier baratte à l'ancienne depuis 1985 dans la rue de l'Orme : son beurre, malaxé au rouleau de bois, tient la comparaison avec n'importe quel autre.",
     en:"Madeleines made with churned Saint-Malo butter, whose hump depends on a shock of temperature. Jean-Yves Bordier has churned by the old method since 1985 in rue de l'Orme: his butter, worked with a wooden roller, stands comparison with any."},
  i:[['salted_butter',200,'g'],['flour',200,'g'],['sugar',180,'g'],['egg',4,'pc'],['baking_powder',1,'tsp'],['honey',2,'tbsp'],['lemon_zest',1,'pc'],['whole_milk',2,'tbsp'],['salt',null,'']],
  s:{fr:["Faites fondre le beurre jusqu'à ce qu'il mousse et sente la noisette, puis laissez-le tiédir : c'est là qu'il donne son goût.","Fouettez les œufs, le sucre et le miel jusqu'au ruban, puis incorporez la farine tamisée avec la levure.","Ajoutez le beurre noisette tiède et le zeste, filmez au contact et laissez reposer 12 heures au réfrigérateur.","Ce repos n'est pas une précaution : c'est lui qui crée la bosse, en retardant la levée jusqu'au four.","Remplissez aux trois quarts des moules beurrés très froids et enfournez 4 minutes à 240 °C, puis 8 minutes à 180 °C."],
     en:["Melt the butter until it foams and smells of hazelnut, then let it cool: that is where the flavour comes from.","Whisk the eggs, sugar and honey to the ribbon, then fold in the flour sifted with the baking powder.","Add the warm browned butter and the zest, cover with cling film touching the surface and rest 12 hours in the fridge.","That rest is not a precaution: it creates the hump, by holding the rise back until the oven.","Fill very cold buttered moulds three-quarters full and bake 4 minutes at 240°C, then 8 minutes at 180°C."]} },

{ id:'craquelins-malouins', c:'eu', lat:48.650, lon:-2.014, base:10, prep:60, cook:25, diff:2, tags:['bread','bake','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f2dfa8','#e8dcc0','#c9a878','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Craquelins malouins',en:'Saint-Malo craquelins'},
  p:{fr:'Saint-Servan, Saint-Malo, France',en:'Saint-Servan, Saint-Malo, France'},
  d:{fr:"Une boule de pâte pochée à l'eau bouillante avant d'être cuite au four, qui sèche en devenant creuse. Les marins malouins l'emportaient en mer : sans levure ni matière grasse, elle se garde des mois et ne moisit pas.",
     en:"A ball of dough poached in boiling water before baking, which dries out hollow. Saint-Malo sailors took it to sea: with no yeast and no fat, it keeps for months and does not mould."},
  i:[['flour',500,'g'],['egg',4,'pc'],['whole_milk',80,'ml'],['sugar',30,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, les œufs, le lait, le sucre et le sel 15 minutes : la pâte doit être très ferme, presque dure à travailler.","Laissez-la reposer une heure sous un linge, puis divisez-la en boules de 40 g bien lisses.","Pochez-les par petites quantités dans une eau frémissante : elles tombent au fond, puis remontent au bout de 3 minutes.","Égouttez-les et laissez-les sécher 30 minutes sur un linge, sans les empiler : c'est ce séchage qui les rendra creuses.","Enfournez 25 minutes à 180 °C, jusqu'à ce qu'elles blondissent et sonnent creux. Elles se conservent des semaines dans une boîte de fer."],
     en:["Knead the flour, eggs, milk, sugar and salt for 15 minutes: the dough should be very firm, almost hard to work.","Rest it for an hour under a cloth, then divide it into smooth 40 g balls.","Poach them in small batches in barely simmering water: they sink, then rise after about 3 minutes.","Drain them and let them dry for 30 minutes on a cloth, without stacking: that drying is what makes them hollow.","Bake for 25 minutes at 180°C, until pale gold and hollow-sounding. They keep for weeks in a tin."]} },

{ id:'huitres-de-cancale-gratinees', c:'eu', lat:48.677, lon:-1.851, base:4, prep:30, cook:10, diff:2, tags:['sea','festive','fast'],
  art:{v:'plate',bg:'#26384a',plate:'#f4ecd8',style:'fish',food:['#f0e8d0','#e0b45a','#7fae5a','#e8dcc0'],garnish:'#6fbf8f'},
  n:{fr:'Huîtres de Cancale gratinées',en:'Grilled Cancale oysters'},
  p:{fr:'Cancale, Ille-et-Vilaine, France',en:'Cancale, Ille-et-Vilaine, France'},
  d:{fr:"Des plates de Cancale passées quelques minutes sous le gril, sous un beurre au cidre et à l'échalote. Les parcs de Cancale approvisionnaient la table de Louis XIV, qui les faisait porter à Versailles par relais de chevaux.",
     en:"Cancale flat oysters given a few minutes under the grill, under a cider and shallot butter. The Cancale beds supplied Louis XIV's table, the oysters carried to Versailles by relays of horses."},
  i:[['oysters',24,'pc'],['salted_butter',150,'g'],['shallot',4,'pc'],['dry_cider',100,'ml'],['breadcrumbs',60,'g'],['parsley',4,'tbsp'],['lemon',2,'pc'],['coarse_salt',500,'g'],['pepper',null,'']],
  s:{fr:["Ouvrez les huîtres au couteau plat et jetez la première eau : elles en refont une seconde, plus fine, en quelques minutes.","Détachez la noix de son muscle pour que chacun n'ait pas à le faire à table.","Faites réduire l'échalote ciselée dans le cidre jusqu'à ce qu'il ne reste presque plus de liquide, puis laissez refroidir.","Travaillez ce mélange avec le beurre demi-sel en pommade et le persil, et déposez-en une noisette sur chaque huître.","Calez les coquilles dans un lit de gros sel, parsemez de chapelure, et passez 3 minutes sous le gril brûlant : le bord doit à peine se rétracter. Au-delà, l'huître se recroqueville et devient caoutchouteuse."],
     en:["Open the oysters with a flat knife and discard the first liquor: they make a second, finer one within minutes.","Free the oyster from its muscle so nobody has to do it at the table.","Reduce the chopped shallot in the cider until almost no liquid remains, then let it cool.","Work this into the softened salted butter with the parsley, and set a hazelnut of it on each oyster.","Steady the shells in a bed of coarse salt, scatter breadcrumbs, and give them 3 minutes under a fierce grill: the edge should barely curl. Longer and the oyster shrivels to rubber."]} },

{ id:'ravioles-au-saint-marcellin', c:'eu', lat:45.157, lon:5.325, base:4, prep:70, cook:5, diff:3, tags:['cheese','comfort','festive'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4f0e6',style:'flat',food:['#f2dfa8','#f0e8d0','#e0b45a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Ravioles au saint-marcellin',en:'Saint-Marcellin ravioles'},
  p:{fr:'Saint-Marcellin, Isère, France',en:'Saint-Marcellin, Isère, France'},
  d:{fr:"De minuscules carrés de pâte, seize par plaque, farcis du fromage de la ville plutôt que du seul comté. Le mot raviole apparaît en Dauphiné dès 1228 ; le fromage, lui, a donné son nom à la ville — ou l'inverse, on ne s'accorde toujours pas.",
     en:"Tiny squares of pasta, sixteen to a sheet, filled with the town's own cheese rather than Comté alone. The word raviole appears in Dauphiné as early as 1228; the cheese gave the town its name — or the reverse, the argument is unsettled."},
  i:[['flour',300,'g'],['egg',3,'pc'],['water',60,'ml'],['saint_marcellin',2,'pc'],['comte_cheese',120,'g'],['fromage_blanc',150,'g'],['parsley',4,'tbsp'],['chives',3,'tbsp'],['garlic',1,'clove'],['butter',40,'g'],['heavy_cream',200,'ml'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine, les œufs, l'eau et le sel 10 minutes, puis laissez reposer la pâte 1 heure au frais sous un linge.","Choisissez des saint-marcellin à point, crémeux sous la croûte : trop jeunes ils restent plâtreux, trop faits ils coulent et détrempent la farce.","Écrasez-les à la fourchette avec le comté râpé, le fromage blanc bien égoutté, l'ail pilé, les herbes et la muscade.","Abaissez la pâte à 0,6 mm — on doit lire à travers — déposez des noisettes de farce tous les 3 cm, couvrez d'une seconde abaisse et soudez du bout des doigts avant de découper à la roulette.","Pochez 1 minute dans l'eau frémissante, jamais bouillante : elles remontent et c'est fini. Servez-les nappées de crème réduite au beurre, éventuellement passées 2 minutes sous le gril."],
     en:["Knead the flour, eggs, water and salt for 10 minutes, then rest the dough for an hour in the cold under a cloth.","Choose Saint-Marcellin at their peak, creamy under the rind: too young they stay chalky, too ripe they run and soak the filling.","Mash them with a fork together with the grated Comté, well-drained fromage blanc, crushed garlic, herbs and nutmeg.","Roll the dough to 0.6 mm — you should be able to read through it — set hazelnuts of filling every 3 cm, cover with a second sheet and seal with your fingertips before cutting with a wheel.","Poach for 1 minute in barely trembling water, never at a boil: they rise and it is done. Serve them coated in cream reduced with butter, or given 2 minutes under the grill."]} },

{ id:'galette-saucisse', c:'eu', lat:48.109, lon:-1.679, base:4, prep:70, cook:20, diff:1, tags:['street','pork','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#c9924a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Galette-saucisse',en:'Galette-saucisse'},
  p:{fr:'Rennes, Ille-et-Vilaine, France',en:'Rennes, Brittany, France'},
  d:{fr:"Une saucisse de porc grillée roulée dans une galette de blé noir froide, mangée debout au marché des Lices et dans les tribunes du Roazhon Park. Ni beurre, ni moutarde, ni ketchup : à Rennes, la question est tranchée depuis longtemps et se rediscute chaque samedi.",
     en:"A grilled pork sausage rolled in a cold buckwheat pancake, eaten standing at the Lices market and in the stands of the Roazhon Park. No butter, no mustard, no ketchup: in Rennes the question was settled long ago and is reopened every Saturday."},
  i:[['buckwheat_flour',330,'g'],['water',750,'ml'],['egg',1,'pc'],['pork_sausage',4,'pc'],['coarse_salt',10,'g'],['butter',20,'g']],
  s:{fr:["Mêlez la farine de blé noir, le gros sel et un tiers de l'eau, et travaillez la pâte à la main jusqu'à ce qu'elle file et fasse des bulles.","Détendez-la avec le reste d'eau et l'œuf, puis laissez-la reposer au moins 3 heures — une nuit vaut mieux : le sarrasin doit s'hydrater complètement.","Cuisez les galettes sur une plaque très chaude à peine graissée, 90 secondes d'un côté, 30 de l'autre, et empilez-les.","Grillez les saucisses lentement, sans les piquer, jusqu'à ce que la peau soit brune et craquante.","Posez la saucisse sur une galette froide et roulez serré. Chaude sur froide : c'est le contraste qui fait tout, et une galette réchauffée casse."],
     en:["Mix the buckwheat flour, coarse salt and a third of the water, and work the batter by hand until it ribbons and bubbles.","Loosen it with the rest of the water and the egg, then rest it at least 3 hours — overnight is better: the buckwheat must hydrate fully.","Cook the pancakes on a very hot, barely greased griddle, 90 seconds on one side, 30 on the other, and stack them.","Grill the sausages slowly, without pricking them, until the skin is brown and crackling.","Set the sausage on a cold pancake and roll it tight. Hot on cold: the contrast is the whole point, and a reheated pancake cracks."]} },

{ id:'andouille-de-guemene', c:'eu', lat:48.070, lon:-3.203, base:6, prep:40, cook:180, diff:3, tags:['pork','slow','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'flat',food:['#6f4a3a','#f0e8d0','#c9924a','#8f6a4a'],garnish:'#7fae6a'},
  n:{fr:'Andouille de Guémené',en:'Guémené andouille'},
  p:{fr:'Guémené-sur-Scorff, Morbihan, France',en:'Guémené-sur-Scorff, Brittany, France'},
  d:{fr:"Des chaudins de porc enfilés les uns dans les autres puis fumés au bois de hêtre, qui dessinent à la coupe des cercles concentriques parfaits. C'est ce montage en poupées russes, et non un hachage, qui donne son dessin à la tranche : une andouille mal enfilée se voit au premier couteau.",
     en:"Pork chitterlings drawn one inside another then smoked over beech, which show perfect concentric rings when sliced. That Russian-doll assembly, not any mincing, is what draws the pattern: a badly threaded andouille shows at the first cut."},
  i:[['pork_chitterlings',2,'kg'],['coarse_salt',80,'g'],['thyme',3,'sprig'],['bay_leaf',4,'pc'],['onion',2,'pc'],['dry_cider',500,'ml'],['potato',1,'kg'],['butter',60,'g'],['pepper',null,'']],
  s:{fr:["Nettoyez et grattez les chaudins à l'eau vinaigrée, puis salez-les au sel sec 24 heures avec le thym et le laurier.","Enfilez-les du plus petit au plus grand, comme des poupées russes, en tirant sans jamais forcer : un chaudin déchiré ruine le dessin.","Bridez le boudin à la ficelle en spirale serrée et laissez-le sécher une nuit au frais.","Fumez-le au bois de hêtre à froid, 6 heures par jour pendant plusieurs semaines pour une andouille de garde — 12 heures suffisent pour une consommation rapide.","Pochez-la 3 heures dans un bouillon de cidre et d'oignon, sans jamais bouillir. Servez tiède, en tranches épaisses, avec des pommes de terre au beurre."],
     en:["Clean and scrape the chitterlings in vinegared water, then dry-salt them for 24 hours with the thyme and bay.","Thread them smallest inside largest, like Russian dolls, pulling but never forcing: a torn casing ruins the pattern.","Truss the roll with string in a tight spiral and let it dry overnight in the cold.","Cold-smoke it over beech, 6 hours a day for several weeks for a keeping andouille — 12 hours is enough for one to be eaten soon.","Poach it for 3 hours in a cider and onion broth, never boiling. Serve warm, in thick slices, with buttered potatoes."]} },

{ id:'moules-a-la-normande', c:'eu', lat:49.365, lon:0.081, base:4, prep:25, cook:15, diff:1, tags:['sea','fast','comfort'],
  art:{v:'pot',bg:'#26384a',plate:'#f4f0e6',style:'stew',food:['#2b3a4a','#f4f0e6','#e8dcc0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Moules à la normande',en:'Normandy mussels'},
  p:{fr:'Trouville-sur-Mer, Calvados, France',en:'Trouville-sur-Mer, Normandy, France'},
  d:{fr:"La marinière enrichie de cidre brut et de crème d'Isigny, née sur la Côte fleurie quand les restaurateurs cherchaient à retenir les Parisiens en villégiature. Le cidre remplace le vin blanc et laisse une pointe d'acidité que la crème arrondit sans l'effacer.",
     en:"Marinière enriched with dry cider and Isigny cream, born on the Côte Fleurie when restaurateurs were trying to keep holidaying Parisians. Cider replaces white wine and leaves an edge of acidity that the cream rounds without erasing."},
  i:[['mussels',2,'kg'],['dry_cider',200,'ml'],['heavy_cream',200,'ml'],['shallot',3,'pc'],['butter',40,'g'],['parsley',4,'tbsp'],['flour',15,'g'],['potato',800,'g'],['frying_oil',1,'l'],['pepper',null,'']],
  s:{fr:["Grattez et ébarbez les moules à l'eau froide et écartez sans hésiter celles qui restent ouvertes sous une pression du doigt.","Faites suer l'échalote ciselée au beurre sans coloration, versez le cidre et laissez bouillonner 2 minutes pour chasser l'âpreté.","Jetez les moules, couvrez et secouez la marmite deux fois : elles sont cuites dès qu'elles s'ouvrent, soit 3 à 4 minutes, pas davantage.","Retirez-les et gardez-les au chaud ; filtrez le jus, liez-le d'un beurre manié et ajoutez la crème hors du feu.","Ne salez qu'à la fin, et souvent pas du tout : l'eau des moules a déjà tout donné. Nappez et servez avec des frites."],
     en:["Scrub and beard the mussels in cold water and discard without hesitation any that stay open under finger pressure.","Sweat the chopped shallot in butter without colour, pour in the cider and let it bubble for 2 minutes to drive off the harshness.","Tip in the mussels, cover and shake the pot twice: they are done the moment they open, 3 to 4 minutes, no more.","Lift them out and keep them warm; strain the liquor, thicken it with beurre manié and add the cream off the heat.","Salt only at the end, and often not at all: the mussel liquor has already given everything. Coat and serve with chips."]} },

{ id:'tarte-au-maroilles', c:'eu', lat:50.130, lon:3.769, base:6, prep:100, cook:35, diff:2, tags:['cheese','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0913a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tarte au maroilles',en:'Maroilles tart'},
  p:{fr:'Maroilles, Nord, France',en:'Maroilles, Hauts-de-France, France'},
  d:{fr:"Une tarte à pâte levée couverte de maroilles fondu, servie tiède avec une bière de garde. Le fromage est né à l'abbaye de Maroilles au Xᵉ siècle ; son odeur redoutable disparaît à la cuisson et ne laisse qu'un goût de noisette et de lait cuit.",
     en:"A risen-dough tart covered with melted Maroilles, served warm with a bière de garde. The cheese was born at Maroilles abbey in the 10th century; its formidable smell vanishes in the oven and leaves only hazelnut and cooked milk."},
  i:[['flour',300,'g'],['fresh_yeast',15,'g'],['whole_milk',150,'ml'],['egg',3,'pc'],['butter',80,'g'],['maroilles_cheese',400,'g'],['heavy_cream',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine, la levure délayée dans le lait tiède, un œuf, le beurre mou et le sel pendant 10 minutes.","Laissez lever 1 h 30 à couvert, puis étalez la pâte dans un moule à bords hauts et laissez-la pousser encore 30 minutes.","Ôtez la croûte orangée du maroilles et taillez-le en lamelles épaisses : c'est la croûte, pas la pâte, qui porte l'odeur.","Battez les œufs restants avec la crème, poivrez généreusement, et ne salez pas — le fromage s'en charge.","Rangez les lamelles sur la pâte, versez l'appareil et enfournez 35 minutes à 200 °C. Laissez tiédir 15 minutes avant de couper, sinon la tarte coule."],
     en:["Knead the flour, the yeast dissolved in warm milk, one egg, the softened butter and salt for 10 minutes.","Prove for 1½ hours covered, then spread the dough in a deep tin and let it rise another 30 minutes.","Cut away the orange rind of the Maroilles and slice it thickly: it is the rind, not the paste, that carries the smell.","Beat the remaining eggs with the cream, pepper generously, and do not salt — the cheese sees to that.","Lay the slices on the dough, pour over the custard and bake for 35 minutes at 200°C. Let it settle for 15 minutes before cutting, or the tart runs."]} },

{ id:'croque-monsieur', c:'eu', lat:48.869, lon:2.330, base:4, prep:20, cook:12, diff:1, tags:['cheese','fast','street'],
  art:{v:'plate',bg:'#33291f',plate:'#f4f0e6',style:'flat',food:['#e0b45a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Croque-monsieur',en:'Croque-monsieur'},
  p:{fr:'Paris, France',en:'Paris, France'},
  d:{fr:"Apparu vers 1910 dans un café de la rue des Capucines, et cité par Proust dès À l'ombre des jeunes filles en fleurs. Le nom vient du bruit sous la dent ; coiffé d'un œuf au plat, il devient madame — la comparaison au chapeau est l'explication la plus souvent avancée.",
     en:"It appeared around 1910 in a café on the rue des Capucines, and Proust mentions it as early as Within a Budding Grove. The name comes from the crunch; crowned with a fried egg it becomes a madame — the hat comparison is the explanation most often offered."},
  i:[['white_bread',8,'slice'],['ham',4,'slice'],['gruyere_cheese',150,'g'],['butter',40,'g'],['whole_milk',300,'ml'],['flour',30,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites une béchamel serrée : roux blond, lait chaud versé en trois fois, 8 minutes d'ébullition douce, muscade et poivre.","Elle doit napper la cuillère et tenir : trop liquide, elle détrempe le pain et le croque s'affaisse.","Beurrez l'extérieur des tranches — jamais l'intérieur, la béchamel s'en charge — et tartinez l'intérieur de sauce.","Garnissez de jambon et de la moitié du gruyère, refermez, puis couvrez le dessus du reste de béchamel et de fromage.","Enfournez 12 minutes à 200 °C, position haute, jusqu'à ce que le dessus boursoufle et brunisse par plaques."],
     en:["Make a tight béchamel: pale roux, hot milk in three additions, 8 minutes at a gentle boil, nutmeg and pepper.","It must coat the spoon and hold: too thin and it soaks the bread, and the croque collapses.","Butter the outside of the slices — never the inside, the béchamel handles that — and spread sauce on the inside.","Fill with ham and half the gruyère, close, then cover the top with the remaining béchamel and cheese.","Bake for 12 minutes at 200°C, high in the oven, until the top blisters and browns in patches."]} },

{ id:'jambon-beurre', c:'eu', lat:48.861, lon:2.345, base:2, prep:10, cook:0, diff:1, tags:['street','fast','pork'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#f4d8c8','#f4f0e6','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Jambon-beurre',en:'Jambon-beurre'},
  p:{fr:'Paris, France',en:'Paris, France'},
  d:{fr:"Le sandwich parisien : une demi-baguette, du beurre, du jambon blanc, rien d'autre. Il n'y a rien derrière quoi se cacher — la qualité tient entièrement aux trois produits, et le beurre doit être à température, jamais sorti du réfrigérateur.",
     en:"The Parisian sandwich: half a baguette, butter, cooked ham, nothing else. There is nothing to hide behind — quality rests entirely on the three products, and the butter must be at room temperature, never straight from the fridge."},
  i:[['baguette',1,'pc'],['butter',80,'g'],['ham',4,'slice'],['pickles',6,'pc'],['salt',null,'']],
  s:{fr:["Choisissez une baguette de tradition cuite le jour même, encore sonore sous le doigt : une baguette molle rend le sandwich mou.","Sortez le beurre une heure à l'avance : froid, il se déchire au lieu de s'étaler et déchire la mie avec lui.","Fendez la baguette sans la traverser, et beurrez généreusement les deux faces, jusqu'aux extrémités.","Pliez le jambon en accordéon plutôt que de le poser à plat : il faut de l'épaisseur et de l'air, pas une feuille écrasée.","Ajoutez quelques cornichons, une pointe de fleur de sel sur le beurre, et mangez dans l'heure."],
     en:["Choose a traditional baguette baked the same day, still ringing under the finger: a soft baguette makes a soft sandwich.","Take the butter out an hour ahead: cold, it tears instead of spreading, and tears the crumb with it.","Split the baguette without cutting through, and butter both faces generously, right to the ends.","Fold the ham in accordion pleats rather than laying it flat: you want thickness and air, not a flattened sheet.","Add a few gherkins, a touch of fleur de sel on the butter, and eat within the hour."]} },

{ id:'kouglof-alsacien', c:'eu', lat:48.196, lon:7.318, base:8, prep:150, cook:45, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9924a','#e8dcb8','#f0e8d0','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Kouglof',en:'Kouglof'},
  p:{fr:'Ribeauvillé, Haut-Rhin, France',en:'Ribeauvillé, Alsace, France'},
  d:{fr:"Une brioche aux raisins cuite dans un moule de terre vernissée à cannelures torsadées, servie le dimanche matin avec un verre de vin blanc. Le moule n'est pas décoratif : sa terre poreuse absorbe l'humidité et fait la croûte fine qu'un moule de métal ne donne jamais.",
     en:"A raisin brioche baked in a glazed earthenware mould with twisted flutes, served on Sunday mornings with a glass of white wine. The mould is not decorative: its porous clay draws off moisture and makes the thin crust a metal tin never gives."},
  i:[['flour',500,'g'],['fresh_yeast',25,'g'],['whole_milk',200,'ml'],['egg',3,'pc'],['butter',150,'g'],['sugar',80,'g'],['raisins',150,'g'],['kirsch',50,'ml'],['almonds',60,'g'],['powdered_sugar',30,'g'],['salt',null,'']],
  s:{fr:["Faites gonfler les raisins dans le kirsch tiède au moins 2 heures, et égouttez-les à fond.","Pétrissez la farine, la levure délayée dans le lait, les œufs, le sucre et le sel 15 minutes, puis incorporez le beurre mou morceau par morceau.","La pâte doit se décoller du bol et claquer : c'est long, et c'est ce qui fait la mie filante.","Laissez lever 1 h 30, incorporez les raisins à la main, et beurrez généreusement le moule avant de coucher une amande entière au fond de chaque cannelure.","Emplissez le moule aux deux tiers, laissez pousser 1 heure, et cuisez 45 minutes à 180 °C. Démoulez chaud et sucrez au sucre glace une fois froid."],
     en:["Plump the raisins in warm kirsch for at least 2 hours, and drain them thoroughly.","Knead the flour, the yeast dissolved in milk, the eggs, sugar and salt for 15 minutes, then work in the soft butter piece by piece.","The dough must leave the bowl and slap: it takes a while, and it is what makes the stringy crumb.","Prove for 1½ hours, fold in the raisins by hand, and butter the mould generously before laying a whole almond in the base of each flute.","Fill the mould two-thirds full, prove for an hour, and bake for 45 minutes at 180°C. Turn out hot and dust with icing sugar once cold."]} },

{ id:'andouillette-de-troyes', c:'eu', lat:48.297, lon:4.074, base:4, prep:20, cook:30, diff:2, tags:['pork','comfort','grill'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'grill',food:['#c9924a','#e8dcb8','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Andouillette de Troyes',en:'Troyes andouillette'},
  p:{fr:'Troyes, Aube, France',en:'Troyes, Champagne, France'},
  d:{fr:"Une andouillette de chaudins coupés en lanières dans la longueur, ce qui lui donne un grain fibreux et non un fondu de charcuterie. La légende veut qu'en 1560 les troupes royales aient interrompu le pillage de Troyes pour en manger, ce qui laissa aux Troyens le temps de fuir.",
     en:"An andouillette of chitterlings cut into lengthwise strips, which gives it a fibrous grain rather than a smooth charcuterie paste. Legend has it that in 1560 royal troops broke off sacking Troyes to eat them, which gave the townspeople time to flee."},
  i:[['andouillette',4,'pc'],['dijon_mustard',3,'tbsp'],['shallot',3,'pc'],['white_wine',200,'ml'],['heavy_cream',150,'ml'],['butter',40,'g'],['potato',800,'g'],['parsley',3,'tbsp'],['pepper',null,'']],
  s:{fr:["Piquez la peau de trois coups d'aiguille seulement : trop d'entailles et l'andouillette se vide en cuisant.","Faites-la dorer à la poêle au beurre, à feu moyen, 12 minutes en la retournant souvent — le feu vif ferait éclater la peau avant que le cœur soit chaud.","Réservez-la au chaud et faites suer l'échalote dans la même poêle, sans la brûler.","Déglacez au vin blanc, laissez réduire de moitié, ajoutez la crème puis la moutarde hors du feu : bouillie, la moutarde devient amère.","Nappez et servez avec des pommes de terre vapeur. Un chablis frais, et rien d'autre."],
     en:["Prick the skin just three times with a needle: too many cuts and the andouillette empties as it cooks.","Brown it in a pan in butter over medium heat for 12 minutes, turning often — fierce heat would burst the skin before the centre is hot.","Set it aside in the warm and sweat the shallot in the same pan, without burning it.","Deglaze with white wine, reduce by half, add the cream then the mustard off the heat: boiled, mustard turns bitter.","Coat and serve with steamed potatoes. A cold Chablis, and nothing else."]} },

{ id:'escargots-de-bourgogne', c:'eu', lat:47.322, lon:5.041, base:4, prep:45, cook:12, diff:2, tags:['festive','fast','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#4f6f3a','#7fae5a','#e8dcb8','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Escargots de Bourgogne',en:'Burgundy snails'},
  p:{fr:'Dijon, Côte-d’Or, France',en:'Dijon, Burgundy, France'},
  d:{fr:"Des escargots remis en coquille sous un beurre d'ail, de persil et d'échalote, passés au four brûlant. Le beurre est le plat : l'escargot lui-même est presque neutre, et l'on sauce la coquille au pain bien après l'avoir vidée.",
     en:"Snails returned to their shells under a butter of garlic, parsley and shallot, given a blast of hot oven. The butter is the dish: the snail itself is nearly neutral, and one mops the shell with bread long after emptying it."},
  i:[['snails',48,'pc'],['butter',250,'g'],['garlic',10,'clove'],['parsley',1,'bunch'],['shallot',3,'pc'],['white_wine',100,'ml'],['bread',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Si vous partez d'escargots frais, faites-les jeûner une semaine, dégorgez-les au gros sel, puis pochez-les 2 heures au court-bouillon.","Hachez l'ail, l'échalote et le persil très finement, puis travaillez-les au beurre pommade avec du sel et beaucoup de poivre.","Le beurre doit être vert et homogène : hachez à la main plutôt qu'au mixeur, qui rend le persil amer et l'ail âcre.","Glissez une noisette de beurre au fond de chaque coquille, l'escargot par-dessus, et rebouchez d'une bonne dose de beurre.","Calez les coquilles ouverture vers le haut, versez un trait de vin blanc au fond du plat, et enfournez 10 minutes à 220 °C : le beurre doit grésiller sans noircir."],
     en:["If starting from live snails, fast them for a week, purge them in coarse salt, then poach them for 2 hours in court-bouillon.","Chop the garlic, shallot and parsley very finely, then work them into softened butter with salt and plenty of pepper.","The butter must be green and even: chop by hand rather than in a blender, which turns the parsley bitter and the garlic acrid.","Slip a hazelnut of butter into each shell, the snail on top, and plug it with a generous amount more.","Wedge the shells opening upward, pour a splash of white wine into the dish, and bake for 10 minutes at 220°C: the butter should sizzle without darkening."]} },

{ id:'praluline', c:'eu', lat:46.036, lon:4.068, base:8, prep:180, cook:35, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9402c','#e8dcb8','#f0e8d0','#e07a6a'],garnish:'#c9754a'},
  n:{fr:'Praluline',en:'Praluline'},
  p:{fr:'Roanne, Loire, France',en:'Roanne, Loire, France'},
  d:{fr:"Une brioche truffée de pralines roses concassées, créée à Roanne en 1955 et déposée depuis. Les pralines fondent partiellement à la cuisson et teignent la mie de traînées framboise ; concassées trop fin, elles disparaissent, trop gros, elles percent la pâte.",
     en:"A brioche studded with crushed pink pralines, created in Roanne in 1955 and trademarked since. The pralines partly melt in the oven and stain the crumb with raspberry streaks; crushed too fine they vanish, too coarse they pierce the dough."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['egg',5,'pc'],['butter',250,'g'],['sugar',60,'g'],['whole_milk',80,'ml'],['praline_rose',300,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, la levure, les œufs, le sucre, le lait et le sel 15 minutes, jusqu'à ce que la pâte claque contre la cuve.","Ajoutez le beurre froid en morceaux, un à un, et pétrissez encore 10 minutes : la pâte doit redevenir lisse et brillante.","Laissez lever 2 heures, dégazez, puis mettez au froid une nuit — une pâte à brioche chaude est impossible à travailler.","Concassez les pralines au rouleau en morceaux de la taille d'un pois, et incorporez-les à la main, en quelques plis seulement.","Façonnez une couronne, laissez pousser 2 heures, et cuisez 35 minutes à 165 °C. À four plus chaud, le sucre des pralines brûlerait avant que la brioche soit cuite."],
     en:["Knead the flour, yeast, eggs, sugar, milk and salt for 15 minutes, until the dough slaps against the bowl.","Add the cold butter in pieces, one at a time, and knead 10 minutes more: the dough must come back smooth and glossy.","Prove for 2 hours, knock back, then chill overnight — warm brioche dough is impossible to handle.","Crush the pralines with a rolling pin to pea-sized pieces, and fold them in by hand, in only a few turns.","Shape a crown, prove for 2 hours, and bake for 35 minutes at 165°C. Any hotter and the praline sugar would burn before the brioche was done."]} },

{ id:'fondue-savoyarde', c:'eu', lat:45.564, lon:5.918, base:4, prep:20, cook:25, diff:2, tags:['cheese','comfort','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f4ecd8',style:'other',food:['#e8dcb8','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Fondue savoyarde',en:'Savoyard fondue'},
  p:{fr:'Chambéry, Savoie, France',en:'Chambéry, Savoy, France'},
  d:{fr:"Trois fromages de Savoie — beaufort, comté et emmental de Savoie — fondus dans un vin blanc d'Apremont. Contrairement à la fribourgeoise, elle mêle des pâtes pressées cuites, qui demandent plus de vin et plus de patience pour ne pas filer en fils.",
     en:"Three Savoy cheeses — Beaufort, Comté and Savoy Emmental — melted in white Apremont wine. Unlike the Fribourg version, it mixes cooked pressed cheeses, which need more wine and more patience if they are not to string."},
  i:[['beaufort_cheese',300,'g'],['comte_cheese',300,'g'],['emmental_cheese',200,'g'],['white_wine',400,'ml'],['garlic',2,'clove'],['cornstarch',1,'tbsp'],['kirsch',30,'ml'],['bread',600,'g'],['nutmeg',1,'pinch'],['pepper',null,'']],
  s:{fr:["Frottez le caquelon d'une gousse d'ail coupée, puis jetez-la — l'ail cru dans le fromage domine tout.","Râpez les trois fromages plutôt que de les couper en dés : ils fondent uniformément et ne forment pas de boules.","Versez le vin, chauffez-le sans le faire bouillir, et ajoutez le fromage par poignées en tournant en huit.","N'ajoutez la poignée suivante que lorsque la précédente a disparu : c'est l'unique moyen d'éviter que la fondue tranche.","Liez d'une cuillerée de fécule délayée dans le kirsch, poivrez, muscadez, et maintenez sur un réchaud très doux. Le pain doit être rassis d'un jour, sinon il se détache de la fourchette."],
     en:["Rub the pot with a cut garlic clove, then discard it — raw garlic in cheese dominates everything.","Grate the three cheeses rather than dicing them: they melt evenly and do not form lumps.","Pour in the wine, heat it without boiling, and add the cheese by handfuls, stirring in figures of eight.","Add the next handful only when the previous one has disappeared: it is the only way to stop the fondue splitting.","Bind with a spoonful of cornstarch slaked in kirsch, add pepper and nutmeg, and keep it over a very low burner. The bread must be a day old, or it falls off the fork."]} },

{ id:'pate-de-pommes-de-terre', c:'eu', lat:46.170, lon:1.870, base:6, prep:50, cook:60, diff:2, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Pâté de pommes de terre',en:'Potato pie'},
  p:{fr:'Guéret, Creuse, France',en:'Guéret, Limousin, France'},
  d:{fr:"Une tourte de pâte feuilletée emplie de pommes de terre crues en lamelles, dans laquelle on verse la crème par une cheminée à la sortie du four. Le plat des fermes de la Creuse, où la pomme de terre remplaçait la viande qu'on n'avait pas.",
     en:"A puff-pastry pie filled with raw sliced potatoes, into which cream is poured through a chimney as it leaves the oven. The dish of Creuse farms, where potato stood in for the meat there was none of."},
  i:[['puff_pastry',600,'g'],['potato',1,'kg'],['onion',2,'pc'],['heavy_cream',250,'ml'],['garlic',2,'clove'],['parsley',4,'tbsp'],['butter',40,'g'],['egg_yolk',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez les pommes de terre en lamelles de 2 mm et ne les rincez surtout pas : c'est leur amidon qui liera la garniture.","Mêlez-les à l'oignon émincé, à l'ail, au persil, au sel et à beaucoup de poivre, avec quelques noisettes de beurre.","Garnissez un fond de pâte, couvrez d'un second disque, soudez à la fourchette et dorez au jaune d'œuf.","Ménagez au centre une cheminée large comme un doigt, tenue par un cornet de papier : sans elle, la vapeur soulève le couvercle.","Cuisez 1 heure à 180 °C. À la sortie, versez la crème brûlante par la cheminée et laissez reposer 10 minutes avant de couper."],
     en:["Slice the potatoes 2 mm thick and on no account rinse them: their starch is what will bind the filling.","Mix them with the sliced onion, garlic, parsley, salt and plenty of pepper, with a few knobs of butter.","Line a base with pastry, cover with a second disc, seal with a fork and glaze with egg yolk.","Cut a chimney in the centre, a finger wide, held open with a paper cone: without it the steam lifts the lid.","Bake for 1 hour at 180°C. On coming out, pour the scalding cream through the chimney and rest for 10 minutes before cutting."]} },

{ id:'pissaladiere', c:'eu', lat:43.696, lon:7.276, base:6, prep:40, cook:80, diff:2, tags:['veg','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#c9924a','#e0b45a','#3a2a1a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Pissaladière',en:'Pissaladière'},
  p:{fr:'Nice, Alpes-Maritimes, France',en:'Nice, French Riviera, France'},
  d:{fr:"Une pâte à pain couverte d'un kilo d'oignons fondus, d'anchois et d'olives de Nice. Le nom vient du pissalat, une purée d'alevins salés dont on badigeonnait la pâte ; les anchois l'ont remplacé, mais le mot est resté.",
     en:"A bread dough covered with a kilo of melted onions, anchovies and Nice olives. The name comes from pissalat, a paste of salted fry once brushed over the dough; anchovies replaced it, but the word stayed."},
  i:[['flour',400,'g'],['fresh_yeast',15,'g'],['olive_oil',120,'ml'],['onion',1.5,'kg'],['anchovy_fillets',16,'pc'],['black_olives',150,'g'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['garlic',2,'clove'],['salt',null,'']],
  s:{fr:["Émincez les oignons très finement et faites-les fondre à l'huile d'olive avec le thym et le laurier, à couvert, 1 heure à feu très doux.","Ils doivent devenir une compote blonde et sans eau, jamais dorée : dès qu'ils colorent, ils deviennent sucrés et le plat perd son équilibre.","Pendant ce temps, pétrissez une pâte à pain souple à l'huile d'olive et laissez-la lever 1 h 30.","Étalez-la en rectangle épais d'un demi-centimètre, garnissez d'oignons refroidis, et dessinez un quadrillage d'anchois.","Posez une olive dans chaque losange et enfournez 20 minutes à 220 °C. Se mange tiède, jamais brûlant."],
     en:["Slice the onions very finely and melt them in olive oil with thyme and bay, covered, for an hour over very low heat.","They must become a pale, dry compote, never golden: the moment they colour they turn sweet and the dish loses its balance.","Meanwhile knead a soft olive-oil bread dough and let it rise for 1½ hours.","Roll it into a rectangle half a centimetre thick, spread with the cooled onions, and lay a lattice of anchovies.","Set an olive in each diamond and bake for 20 minutes at 220°C. Eaten warm, never scalding."]} },

{ id:'salade-nicoise', c:'eu', lat:43.695, lon:7.271, base:4, prep:30, cook:10, diff:1, tags:['fresh','sea','fast'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4f0e6',style:'salad',food:['#c9402c','#7fae5a','#e8c46a','#3a2a1a'],garnish:'#6fbf8f'},
  n:{fr:'Salade niçoise',en:'Salade niçoise'},
  p:{fr:'Nice, Alpes-Maritimes, France',en:'Nice, French Riviera, France'},
  d:{fr:"Des tomates, des fèves ou des petits artichauts, des anchois et de l'œuf dur, assaisonnés d'huile d'olive et rien d'autre. Les Niçois sont formels : ni pommes de terre, ni haricots verts, ni vinaigre, ni aucun légume cuit — c'est une salade de légumes crus.",
     en:"Tomatoes, broad beans or small artichokes, anchovies and hard-boiled egg, dressed with olive oil and nothing else. The Niçois are firm about it: no potatoes, no green beans, no vinegar, no cooked vegetable at all — it is a raw vegetable salad."},
  i:[['ripe_tomato',800,'g'],['broad_beans',300,'g'],['spring_onion',4,'pc'],['red_pepper',1,'pc'],['cucumber',1,'pc'],['egg',4,'pc'],['anchovy_fillets',12,'pc'],['canned_tuna',200,'g'],['black_olives',100,'g'],['basil',1,'bunch'],['garlic',1,'clove'],['olive_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Coupez les tomates en quartiers, salez-les et laissez-les dégorger 20 minutes dans une passoire : leur eau délaverait la salade.","Écossez les fèves et retirez la seconde peau si elles ne sont plus toutes jeunes ; taillez le poivron et le concombre finement.","Frottez le saladier d'ail, puis disposez les légumes crus sans les mélanger.","Ajoutez les œufs durs en quartiers, les anchois, le thon et les olives, et déchirez le basilic à la main — le couteau le noircit.","Arrosez d'huile d'olive uniquement, salez, et servez sans attendre. Le vinaigre est le seul interdit sur lequel tout Nice s'accorde."],
     en:["Quarter the tomatoes, salt them and let them drain for 20 minutes in a colander: their water would wash out the salad.","Pod the broad beans and slip off the inner skin if they are no longer young; slice the pepper and cucumber thinly.","Rub the bowl with garlic, then arrange the raw vegetables without tossing them.","Add the quartered hard-boiled eggs, anchovies, tuna and olives, and tear the basil by hand — a knife blackens it.","Dress with olive oil only, salt, and serve at once. Vinegar is the one prohibition all Nice agrees on."]} },

{ id:'tapenade', c:'eu', lat:44.361, lon:5.140, base:6, prep:20, cook:0, diff:1, tags:['veg','fast','fresh'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#3a2a1a','#4f3a2a','#7fae5a','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Tapenade',en:'Tapenade'},
  p:{fr:'Nyons, Drôme, France',en:'Nyons, Provence, France'},
  d:{fr:"Une pâte d'olives noires, de câpres et d'anchois pilée au mortier. Le nom vient de tapeno, la câpre en provençal, et non de l'olive : c'est elle, minoritaire en poids, qui donne son nom au plat et son acidité à l'ensemble.",
     en:"A paste of black olives, capers and anchovies pounded in a mortar. The name comes from tapeno, Provençal for caper, not from the olive: the caper, a minority by weight, gives the dish its name and the whole its acidity."},
  i:[['black_olives',300,'g'],['capers',80,'g'],['anchovy_fillets',6,'pc'],['garlic',1,'clove'],['olive_oil',100,'ml'],['lemon',1,'pc'],['thyme',2,'sprig'],['brandy',1,'tbsp'],['pepper',null,'']],
  s:{fr:["Dénoyautez les olives une à une au couteau plutôt qu'à la machine, qui écrase le noyau et laisse de l'amertume.","Rincez les câpres si elles sont au sel, épongez-les, et dessalez les anchois quelques minutes à l'eau froide.","Pilez au mortier l'ail, les câpres puis les anchois, avant d'ajouter les olives par poignées.","Versez l'huile en filet, comme pour une mayonnaise, jusqu'à obtenir une pâte grumeleuse — jamais lisse : le mixeur donne une purée sans caractère.","Relevez de jus de citron, de thym effeuillé, d'une cuillerée d'eau-de-vie et de poivre. Ne salez pas : câpres et anchois s'en chargent. Laissez reposer une nuit."],
     en:["Stone the olives one by one with a knife rather than by machine, which crushes the pit and leaves bitterness.","Rinse the capers if they are salted, pat them dry, and soak the anchovies a few minutes in cold water.","Pound the garlic, then the capers, then the anchovies in a mortar, before adding the olives by handfuls.","Trickle in the oil as for mayonnaise, until you have a lumpy paste — never smooth: a blender gives a purée without character.","Sharpen with lemon juice, picked thyme, a spoonful of brandy and pepper. Do not salt: capers and anchovies see to that. Rest overnight."]} },

{ id:'calissons-d-aix', c:'eu', lat:43.529, lon:5.447, base:24, prep:120, cook:15, diff:3, tags:['sweet','festive','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#f2dfa8','#f4f0e6','#e8c46a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Calissons d’Aix',en:'Calissons of Aix'},
  p:{fr:'Aix-en-Provence, Bouches-du-Rhône, France',en:'Aix-en-Provence, Provence, France'},
  d:{fr:"Des losanges de pâte d'amande et de melon confit posés sur du papier azyme et glacés au blanc d'œuf. La tradition les rattache aux noces du roi René en 1454, où la reine, réputée peu souriante, aurait goûté la friandise : di calin soun, ce sont des câlins.",
     en:"Diamonds of almond and candied melon paste set on rice paper and iced with egg white. Tradition ties them to King René's wedding in 1454, where the queen, said to smile rarely, tasted the sweet: di calin soun, they are little hugs."},
  i:[['ground_almonds',400,'g'],['melon_confit',250,'g'],['orange_zest',60,'g'],['sugar',200,'g'],['orange_blossom_water',2,'tbsp'],['rice_paper',4,'sheet'],['egg_white',1,'pc'],['powdered_sugar',200,'g'],['lemon',1,'pc']],
  s:{fr:["Épongez soigneusement le melon confit et l'écorce d'orange : une pâte trop humide ne sèchera jamais et le glaçage craquellera.","Mixez-les avec les amandes en poudre et le sucre jusqu'à obtenir une pâte souple, puis parfumez à la fleur d'oranger.","Faites-la dessécher 10 minutes à la casserole en remuant sans arrêt, jusqu'à ce qu'elle se détache des parois.","Étalez-la sur le papier azyme à 1 cm d'épaisseur, laissez sécher 12 heures à l'air libre, puis découpez les losanges à l'emporte-pièce.","Montez le blanc en neige avec le sucre glace et le jus de citron, glacez le dessus, et passez 8 minutes au four à 100 °C, porte entrouverte : le glaçage doit durcir sans blondir."],
     en:["Blot the candied melon and orange peel thoroughly: too wet a paste will never dry and the icing will craze.","Blend them with the ground almonds and sugar to a supple paste, then scent with orange blossom water.","Dry it out for 10 minutes in a pan, stirring constantly, until it comes away from the sides.","Spread it on the rice paper 1 cm thick, leave to dry for 12 hours in the open air, then cut out the diamonds.","Whisk the egg white with icing sugar and lemon juice, ice the tops, and give them 8 minutes at 100°C with the door ajar: the icing must set without colouring."]} },

{ id:'magret-de-canard', c:'eu', lat:43.494, lon:0.923, base:4, prep:15, cook:15, diff:2, tags:['poultry','fast','sunday'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'grill',food:['#8f3b2a','#6f2a2a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Magret de canard',en:'Duck magret'},
  p:{fr:'Samatan, Gers, France',en:'Samatan, Gascony, France'},
  d:{fr:"Le filet du canard gras, saisi côté peau jusqu'à ce que la graisse rende, servi rosé. Le mot magret est une invention gasconne des années 1960 : jusque-là on ne mangeait le canard gras qu'en confit, et l'idée de le traiter comme une pièce de bœuf passait pour une provocation.",
     en:"The breast of the fattened duck, seared skin-side until the fat renders, served pink. The word magret is a Gascon invention of the 1960s: until then fattened duck was eaten only as confit, and treating it like a piece of beef was thought a provocation."},
  i:[['duck_breast',2,'pc'],['coarse_salt',1,'tbsp'],['honey',1,'tbsp'],['red_wine_vinegar',2,'tbsp'],['shallot',2,'pc'],['red_wine',150,'ml'],['potato',800,'g'],['duck_fat',60,'g'],['garlic',3,'clove'],['parsley',3,'tbsp'],['pepper',null,'']],
  s:{fr:["Quadrillez la peau au couteau sans entamer la chair : les entailles laissent la graisse s'échapper au lieu de gonfler la peau.","Posez les magrets peau vers le bas dans une poêle froide, puis montez à feu moyen : partir à froid est ce qui rend la graisse au lieu de la brûler.","Comptez 8 minutes côté peau en vidant la graisse trois fois, puis 3 minutes côté chair seulement.","Laissez reposer 8 minutes sous une feuille d'aluminium, chair vers le haut — sans ce repos, tout le jus part sur la planche.","Déglacez la poêle au vinaigre et au miel, ajoutez l'échalote et le vin, réduisez. Servez tranché en biais, avec des pommes sarladaises à la graisse de canard."],
     en:["Score the skin in a lattice without cutting the flesh: the cuts let the fat escape rather than swelling the skin.","Lay the breasts skin down in a cold pan, then bring it to medium heat: starting cold is what renders the fat instead of burning it.","Give them 8 minutes on the skin, pouring off the fat three times, then 3 minutes on the flesh side only.","Rest for 8 minutes under foil, flesh upward — without that rest all the juice ends up on the board.","Deglaze the pan with vinegar and honey, add the shallot and wine, reduce. Serve sliced on the bias, with sarladaise potatoes in duck fat."]} },

{ id:'foie-gras-du-perigord', c:'eu', lat:44.890, lon:1.216, base:8, prep:60, cook:25, diff:3, tags:['festive','sunday','slow'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Foie gras mi-cuit du Périgord',en:'Périgord foie gras terrine'},
  p:{fr:'Sarlat-la-Canéda, Dordogne, France',en:'Sarlat-la-Canéda, Périgord, France'},
  d:{fr:"Un foie d'oie ou de canard déveiné, assaisonné, tassé en terrine et cuit à basse température. Toute la difficulté tient au déveinage : un foie sorti à température ambiante se laisse ouvrir sans se briser, un foie froid casse en morceaux.",
     en:"A goose or duck liver deveined, seasoned, packed into a terrine and cooked at low temperature. The whole difficulty is in the deveining: a liver brought to room temperature opens without breaking, a cold one shatters."},
  i:[['foie_gras',600,'g'],['coarse_salt',9,'g'],['sugar',2,'g'],['port_wine',40,'ml'],['brandy',20,'ml'],['bread',1,'pc'],['pepper',null,'']],
  s:{fr:["Sortez le foie 1 heure à l'avance et laissez-le atteindre 18 °C : c'est la seule température à laquelle il se déveine proprement.","Ouvrez chaque lobe à plat et tirez les veines principales à la pince, en suivant leur ramification, sans chercher à récupérer les plus fines.","Assaisonnez sur les deux faces — 12 g de sel et 3 g de poivre au kilo, jamais au jugé — puis arrosez de porto et d'eau-de-vie, et laissez mariner 12 heures au froid.","Tassez dans la terrine en chassant l'air à chaque couche, et cuisez au bain-marie à 90 °C jusqu'à 55 °C à cœur, soit 25 minutes environ.","Pressez d'un poids, laissez prendre 48 heures au réfrigérateur, et tranchez au couteau trempé dans l'eau chaude. Se sert frais mais non glacé, sur du pain grillé tiède."],
     en:["Take the liver out an hour ahead and let it reach 18°C: it is the only temperature at which it deveins cleanly.","Open each lobe flat and draw out the main veins with tweezers, following their branching, without chasing the finest ones.","Season both faces — 12 g of salt and 3 g of pepper per kilo, never by eye — then moisten with port and brandy, and marinate 12 hours in the cold.","Pack into the terrine, expelling air at each layer, and cook in a bain-marie at 90°C until the centre reaches 55°C, about 25 minutes.","Press under a weight, set for 48 hours in the fridge, and slice with a knife dipped in hot water. Serve cool but not chilled, on warm toast."]} },

{ id:'farci-poitevin', c:'eu', lat:46.325, lon:-0.590, base:8, prep:60, cook:180, diff:2, tags:['veg','slow','sunday'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#4f6f3a','#7fae5a','#e8dcb8','#c9924a'],garnish:'#6fbf8f'},
  n:{fr:'Farci poitevin',en:'Poitevin farci'},
  p:{fr:'Coulon, Marais poitevin, France',en:'Coulon, Marais Poitevin, France'},
  d:{fr:"Un pain de verdure — oseille, épinards, chou, poireau — lié aux œufs et enfermé dans des feuilles de chou vertes, poché trois heures. Le plat de Pâques du Marais poitevin, qui se mange froid, en tranches, dans les barques.",
     en:"A loaf of greens — sorrel, spinach, cabbage, leek — bound with egg and wrapped in green cabbage leaves, poached for three hours. The Easter dish of the Marais Poitevin, eaten cold, in slices, in the punts."},
  i:[['sorrel',300,'g'],['spinach',500,'g'],['green_cabbage',1,'pc'],['leek',3,'pc'],['swiss_chard',300,'g'],['egg',6,'pc'],['smoked_bacon',200,'g'],['garlic',4,'clove'],['parsley',1,'bunch'],['bread',150,'g'],['whole_milk',150,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Blanchissez les grandes feuilles du chou 3 minutes et rafraîchissez-les : elles doivent plier sans casser pour envelopper le farci.","Hachez toutes les verdures crues, très finement, et salez-les une demi-heure pour qu'elles rendent leur eau ; pressez-les à fond.","Une verdure mal essorée donne un farci qui se délite à la cuisson : c'est la seule vraie difficulté du plat.","Mêlez-les aux œufs battus, à la mie trempée dans le lait, au lard haché, à l'ail et au persil.","Tapissez un linge de feuilles de chou, garnissez, nouez serré comme un baluchon et pochez 3 heures à l'eau frémissante. Laissez refroidir sous presse avant de trancher."],
     en:["Blanch the large cabbage leaves for 3 minutes and refresh them: they must fold without cracking to wrap the farci.","Chop all the greens raw, very finely, and salt them for half an hour so they give up their water; press them hard.","Poorly drained greens make a farci that falls apart as it cooks: that is the only real difficulty in the dish.","Mix them with the beaten eggs, the crumb soaked in milk, the chopped bacon, the garlic and parsley.","Line a cloth with cabbage leaves, fill it, tie it tight like a bundle and poach for 3 hours in barely simmering water. Cool under a weight before slicing."]} },

{ id:'pate-de-chartres', c:'eu', lat:48.444, lon:1.489, base:8, prep:90, cook:75, diff:3, tags:['festive','bake','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#c9924a','#8f5a3a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Pâté de Chartres',en:'Chartres pâté'},
  p:{fr:'Chartres, Eure-et-Loir, France',en:'Chartres, Eure-et-Loir, France'},
  d:{fr:"Un pâté en croûte de gibier à plumes, traditionnellement de perdrix rouge, offert aux évêques de Chartres depuis le XVIᵉ siècle. La gelée n'est pas un décor : coulée à froid par la cheminée, elle chasse l'air et conserve le pâté plusieurs semaines.",
     en:"A raised game pie of feathered game, traditionally red-legged partridge, presented to the bishops of Chartres since the 16th century. The jelly is not decoration: poured in cold through the chimney, it drives out the air and keeps the pie for weeks."},
  i:[['shortcrust_pastry',700,'g'],['partridge',2,'pc'],['pork_shoulder',400,'g'],['pork_belly',300,'g'],['foie_gras',150,'g'],['brandy',60,'ml'],['shallot',3,'pc'],['juniper_berries',10,'pc'],['gelatin',10,'g'],['chicken_broth',400,'ml'],['egg_yolk',1,'pc'],['pistachios',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Désossez les perdrix, gardez les filets entiers et hachez le reste avec le porc, l'échalote et le genièvre.","Faites mariner filets et farce 12 heures au cognac : sans marinade, le gibier reste sec et sans parfum.","Foncez un moule à pâté de pâte, alternez farce, filets, foie gras et pistaches, en tassant à chaque couche.","Couvrez, soudez, dorez au jaune et ménagez deux cheminées ; cuisez 15 minutes à 210 °C puis 1 heure à 160 °C.","Laissez refroidir complètement, puis coulez par les cheminées la gelée tiède mais non prise. Attendez 48 heures avant de trancher : le pâté doit se raffermir."],
     en:["Bone the partridges, keep the breasts whole and mince the rest with the pork, shallot and juniper.","Marinate breasts and forcemeat for 12 hours in brandy: without it the game stays dry and scentless.","Line a pie mould with pastry, alternate forcemeat, breasts, foie gras and pistachios, pressing at each layer.","Cover, seal, glaze with yolk and cut two chimneys; bake 15 minutes at 210°C then an hour at 160°C.","Cool completely, then pour the jelly, warm but not set, through the chimneys. Wait 48 hours before slicing: the pie must firm up."]} },

{ id:'gaufre-lilloise', c:'eu', lat:50.641, lon:3.063, base:12, prep:120, cook:20, diff:2, tags:['sweet','street','bake'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Gaufre lilloise',en:'Lille waffle'},
  p:{fr:'Lille, Nord, France',en:'Lille, Hauts-de-France, France'},
  d:{fr:"Une gaufre ovale et plate, fendue à chaud et fourrée d'une crème à la vergeoise et à la vanille de Madagascar. Elle se garde des jours et se transporte : c'est ce qui en a fait, depuis 1849, le cadeau que l'on rapporte de Lille.",
     en:"A flat oval waffle, split while hot and filled with a cream of brown beet sugar and Madagascar vanilla. It keeps for days and travels: which is what has made it, since 1849, the thing you bring back from Lille."},
  i:[['flour',400,'g'],['fresh_yeast',20,'g'],['butter',200,'g'],['egg',2,'pc'],['whole_milk',120,'ml'],['sugar',60,'g'],['vergeoise',250,'g'],['vanilla',1,'pc'],['rum',20,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte levée riche avec la farine, la levure, le lait tiède, les œufs, 80 g de beurre et le sucre, et laissez lever 1 h 30.","Divisez en boules de 50 g, laissez pousser 30 minutes, puis cuisez 90 secondes dans un gaufrier plat bien chaud.","Fendez chaque gaufre à l'horizontale pendant qu'elle est brûlante : refroidie, elle s'émiette au couteau.","Travaillez le reste de beurre en pommade avec la vergeoise, la vanille grattée et le rhum, jusqu'à ce que le sucre ne crisse plus sous la spatule.","Garnissez d'une couche fine, refermez et pressez légèrement. Laissez reposer une nuit : la crème doit imprégner la pâte."],
     en:["Knead a rich yeasted dough with the flour, yeast, warm milk, eggs, 80 g of butter and the sugar, and prove for 1½ hours.","Divide into 50 g balls, prove for 30 minutes, then bake 90 seconds in a hot flat waffle iron.","Split each waffle horizontally while it is scalding: once cool it crumbles under the knife.","Cream the remaining butter with the vergeoise, scraped vanilla and rum, until the sugar no longer grates under the spatula.","Fill with a thin layer, close and press lightly. Rest overnight: the cream must soak into the dough."]} },

{ id:'figatellu', c:'eu', lat:42.700, lon:9.450, base:4, prep:30, cook:20, diff:2, tags:['pork','grill','comfort'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ecd8',style:'grill',food:['#6f2a2a','#8f3b2a','#e8dcb8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Figatellu',en:'Figatellu'},
  p:{fr:'Bastia, Haute-Corse, France',en:'Bastia, Upper Corsica, France'},
  d:{fr:"Une saucisse corse de foie et de viande de porc, fumée au bois de châtaignier, grillée sur les braises et mangée sur du pain qui recueille la graisse. Elle ne se fait qu'en hiver, de novembre à mars, quand les porcs coureurs ont fini de manger les châtaignes.",
     en:"A Corsican sausage of pork liver and meat, smoked over chestnut wood, grilled on coals and eaten on bread that catches the fat. It is made only in winter, from November to March, when the free-ranging pigs have finished the chestnuts."},
  i:[['pork_liver',500,'g'],['pork_shoulder',700,'g'],['pork_belly',300,'g'],['garlic',6,'clove'],['red_wine',150,'ml'],['sausage_casings',null,''],['bread',400,'g'],['brocciu',200,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le foie et les viandes au couteau, en petits dés : le hachoir écrase le foie et donne une pâte amère.","Salez à 25 g au kilo, poivrez fort, ajoutez l'ail pilé et le vin rouge, et laissez reposer 24 heures au froid.","Embossez sans serrer et laissez sécher trois jours dans un endroit frais et ventilé.","Fumez au bois de châtaignier à froid une semaine, une heure ou deux par jour : le fumage doit parfumer, non cuire.","Grillez le figatellu sur les braises, fendu en deux, et servez-le sur une tranche de pain posée dessous pendant la cuisson, avec du brocciu frais."],
     en:["Cut the liver and meats by knife into small dice: a mincer crushes the liver and gives a bitter paste.","Salt at 25 g per kilo, pepper heavily, add the crushed garlic and red wine, and rest for 24 hours in the cold.","Fill the casings loosely and dry for three days somewhere cool and airy.","Cold-smoke over chestnut wood for a week, an hour or two a day: the smoke should scent, not cook.","Grill the figatellu on the coals, split lengthwise, and serve it on a slice of bread placed beneath it while it cooks, with fresh brocciu."]} },

{ id:'fougasse-aux-olives', c:'eu', lat:43.293, lon:5.570, base:6, prep:120, cook:20, diff:2, tags:['bread','bake','veg'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#c9924a','#3a2a1a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Fougasse aux olives',en:'Olive fougasse'},
  p:{fr:'Aubagne, Bouches-du-Rhône, France',en:'Aubagne, Provence, France'},
  d:{fr:"Un pain plat entaillé en épi, jeté au four pour en éprouver la chaleur avant d'y enfourner les vraies fournées. C'est de cet usage — la focacia romaine, le pain du foyer — que la fougasse tire son nom et sa forme ajourée.",
     en:"A flat bread slashed into an ear of wheat, thrown into the oven to test its heat before the real batches went in. From that use — the Roman focacia, the hearth bread — the fougasse takes its name and its open-worked shape."},
  i:[['flour',500,'g'],['fresh_yeast',15,'g'],['olive_oil',80,'ml'],['warm_water',300,'ml'],['black_olives',200,'g'],['green_olives',100,'g'],['rosemary',3,'sprig'],['coarse_salt',10,'g'],['salt',null,'']],
  s:{fr:["Pétrissez farine, levure, eau tiède, sel et la moitié de l'huile 12 minutes, jusqu'à une pâte souple et légèrement collante.","Laissez lever 1 h 30, puis incorporez les olives dénoyautées et le romarin en pliant la pâte, sans la pétrir de nouveau.","Étalez à la main en ovale d'un centimètre, sur une plaque, et laissez détendre 20 minutes.","Entaillez franchement de part en part avec un coupe-pâte, puis écartez les entailles à la main : si elles ne traversent pas, elles se referment à la cuisson.","Huilez, salez au gros sel et enfournez 18 minutes à 240 °C avec un peu de vapeur."],
     en:["Knead the flour, yeast, warm water, salt and half the oil for 12 minutes, to a supple, slightly tacky dough.","Prove for 1½ hours, then fold in the stoned olives and rosemary, without kneading again.","Stretch by hand into a one-centimetre oval on a tray, and let it relax for 20 minutes.","Cut boldly right through with a scraper, then pull the cuts open by hand: if they do not go through, they close again in the oven.","Oil, scatter coarse salt and bake for 18 minutes at 240°C with a little steam."]} },

{ id:'pompe-a-huile', c:'eu', lat:43.949, lon:4.806, base:8, prep:150, cook:25, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Pompe à huile',en:'Pompe à huile'},
  p:{fr:'Avignon, Vaucluse, France',en:'Avignon, Provence, France'},
  d:{fr:"Une galette briochée à l'huile d'olive et à la fleur d'oranger, l'un des treize desserts du gros souper de Noël provençal. On la rompt à la main et jamais au couteau : couper la pompe, dit-on, ruinerait l'année qui vient.",
     en:"A brioche-like flatbread with olive oil and orange blossom, one of the thirteen desserts of the Provençal Christmas supper. It is broken by hand and never cut: cutting the pompe, they say, would ruin the coming year."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['olive_oil',150,'ml'],['sugar',120,'g'],['orange_blossom_water',3,'tbsp'],['orange_zest',1,'pc'],['warm_water',180,'ml'],['salt',null,'']],
  s:{fr:["Faites un levain avec la levure, un peu d'eau tiède et 100 g de farine, et laissez-le doubler 1 heure.","Ajoutez le reste de farine, le sucre, l'huile d'olive, l'eau de fleur d'oranger et le zeste, et pétrissez 10 minutes.","La pâte doit rester molle et huileuse : ajoutez de l'eau plutôt que de la farine si elle résiste.","Laissez lever 2 heures, aplatissez en disque de 2 cm et entaillez de six coups en étoile, bien écartés.","Cuisez 25 minutes à 180 °C et badigeonnez d'huile d'olive et de fleur d'oranger à la sortie du four."],
     en:["Make a starter with the yeast, a little warm water and 100 g of flour, and let it double for an hour.","Add the rest of the flour, the sugar, olive oil, orange blossom water and zest, and knead for 10 minutes.","The dough must stay soft and oily: add water rather than flour if it resists.","Prove for 2 hours, flatten to a 2 cm disc and cut six well-spaced slashes in a star.","Bake for 25 minutes at 180°C and brush with olive oil and orange blossom water as it leaves the oven."]} },

{ id:'bugnes-lyonnaises', c:'eu', lat:45.767, lon:4.833, base:8, prep:90, cook:20, diff:2, tags:['sweet','fry','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#f2dfa8','#e0b45a','#f4f0e6','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Bugnes lyonnaises',en:'Lyon bugnes'},
  p:{fr:'Lyon, Rhône, France',en:'Lyon, Rhône, France'},
  d:{fr:"Des losanges de pâte frits pour le carnaval, à Lyon fines et croustillantes, en Savoie épaisses et moelleuses. La dispute est ancienne et sans arbitre : elle tient à l'épaisseur de l'abaisse et au repos de la pâte, pas à la recette.",
     en:"Diamonds of dough fried for carnival, thin and crisp in Lyon, thick and soft in Savoy. The quarrel is old and unrefereed: it hangs on how thin the dough is rolled and how long it rests, not on the recipe."},
  i:[['flour',500,'g'],['egg',4,'pc'],['butter',100,'g'],['sugar',80,'g'],['fresh_yeast',10,'g'],['orange_blossom_water',2,'tbsp'],['lemon_zest',1,'pc'],['rum',30,'ml'],['frying_oil',1.5,'l'],['powdered_sugar',80,'g'],['salt',null,'']],
  s:{fr:["Pétrissez tous les ingrédients sauf l'huile et le sucre glace, 10 minutes, jusqu'à une pâte lisse et non collante.","Laissez-la reposer au froid au moins 4 heures : c'est le repos qui rend la bugne cassante plutôt que caoutchouteuse.","Abaissez très fin — 2 mm pour la lyonnaise — et découpez des losanges fendus au centre, en passant une pointe dans la fente.","Chauffez l'huile à 170 °C : plus chaude, la bugne brunit sans gonfler ; plus froide, elle boit l'huile.","Frites 40 secondes par face, égouttées sur papier, sucrées au sucre glace une fois tièdes. Elles se mangent le jour même."],
     en:["Knead everything except the oil and icing sugar for 10 minutes, to a smooth, non-sticky dough.","Rest it in the cold for at least 4 hours: that rest is what makes a bugne snap rather than chew.","Roll very thin — 2 mm for the Lyon version — and cut slit diamonds, passing one tip through the slit.","Heat the oil to 170°C: hotter, and the bugne browns without puffing; cooler, and it drinks the oil.","Fry 40 seconds a side, drain on paper, dust with icing sugar once warm. They are eaten the same day."]} },

{ id:'barboton-ardechois', c:'eu', lat:44.620, lon:4.390, base:6, prep:30, cook:60, diff:1, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'other',food:['#4f6f3a','#7fae5a','#f2dfa8','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Barboton de blettes',en:'Chard barboton'},
  p:{fr:'Aubenas, Ardèche, France',en:'Aubenas, Ardèche, France'},
  d:{fr:"Un gratin de blettes et de pommes de terre à la tome de brebis, plat du jardin quand les blettes montent toutes en même temps. Barboter, en ardéchois, c'est faire tremper : les côtes barbotent dans la crème pendant que les feuilles restent en surface.",
     en:"A gratin of chard and potatoes with ewe's tome, the garden dish for when the chard all bolts at once. To barboter, in Ardèche dialect, is to soak: the stems soak in the cream while the leaves stay on top."},
  i:[['swiss_chard',1,'kg'],['potato',400,'g'],['heavy_cream',200,'ml'],['egg',2,'pc'],['tome_fraiche',150,'g'],['garlic',2,'clove'],['onion',1,'pc'],['butter',40,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Séparez les côtes des feuilles : les côtes demandent 15 minutes de cuisson, les feuilles trois.","Taillez les côtes en tronçons et faites-les blanchir à l'eau salée, puis égouttez-les longuement.","Faites tomber les feuilles à la poêle avec l'oignon et l'ail, et pressez-les pour en chasser toute l'eau.","Mêlez les deux aux pommes de terre en fines rondelles crues, à la crème battue avec les œufs, à la muscade et à la moitié de la tome.","Versez dans un plat beurré, couvrez du reste de fromage et cuisez 1 heure à 180 °C. Laissez reposer 10 minutes avant de servir."],
     en:["Separate the stems from the leaves: the stems need 15 minutes' cooking, the leaves three.","Cut the stems into lengths and blanch them in salted water, then drain them well.","Wilt the leaves in a pan with the onion and garlic, and press them to drive out all the water.","Combine both with thinly sliced raw potato, the cream beaten with the eggs, nutmeg and half the tome.","Turn into a buttered dish, cover with the remaining cheese and bake for an hour at 180°C. Rest 10 minutes before serving."]} },

{ id:'roquefort-poires-noix', c:'eu', lat:43.980, lon:2.985, base:4, prep:15, cook:0, diff:1, tags:['cheese','fast','fresh'],
  art:{v:'board',bg:'#2c3440',plate:'#f4f0e6',style:'other',food:['#f4f0e6','#7f8fa0','#e0b45a','#8f6a4a'],garnish:'#7fae6a'},
  n:{fr:'Roquefort, poires et noix',en:'Roquefort with pears and walnuts'},
  p:{fr:'Roquefort-sur-Soulzon, Aveyron, France',en:'Roquefort-sur-Soulzon, Aveyron, France'},
  d:{fr:"Le premier fromage protégé de France — un arrêt du parlement de Toulouse en 1666, une AOC en 1925 —, affiné dans les fleurines du Combalou, ces failles qui ventilent naturellement les caves. Servi simplement, avec des poires et des noix, il n'a besoin de rien d'autre.",
     en:"France's first protected cheese — a Toulouse parliament ruling in 1666, an appellation in 1925 — ripened in the fleurines of the Combalou, the fissures that naturally ventilate the caves. Served plainly, with pears and walnuts, it needs nothing else."},
  i:[['roquefort_cheese',300,'g'],['pears',4,'pc'],['walnuts',100,'g'],['bread',300,'g'],['honey',2,'tbsp'],['butter',40,'g'],['pepper',null,'']],
  s:{fr:["Sortez le roquefort une heure à l'avance : glacé, sa pâte est sèche et son piquant écrase tout le reste.","Coupez-le au fil plutôt qu'au couteau, en portions triangulaires prises du centre vers la croûte, pour que chacun ait autant de bleu.","Choisissez des poires justes mûres, fermes sous le pouce, et coupez-les au dernier moment.","Faites griller les cerneaux de noix à sec, 3 minutes, jusqu'à ce qu'ils sentent — cette torréfaction courte suffit à réveiller l'huile.","Servez sur une planche avec du pain de campagne beurré et un filet de miel. Un vin doux, jamais un rouge tannique."],
     en:["Take the Roquefort out an hour ahead: chilled, its paste is dry and its bite crushes everything else.","Cut it with a wire rather than a knife, in wedges taken from the centre out to the rind, so each portion carries as much blue.","Choose pears just ripe, firm under the thumb, and cut them at the last moment.","Toast the walnut halves dry for 3 minutes, until they smell — that short roasting is enough to wake the oil.","Serve on a board with buttered country bread and a trickle of honey. A sweet wine, never a tannic red."]} },

{ id:'pogne-de-romans', c:'eu', lat:45.045, lon:5.052, base:8, prep:180, cook:35, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Pogne de Romans',en:'Pogne de Romans'},
  p:{fr:'Romans-sur-Isère, Drôme, France',en:'Romans-sur-Isère, Drôme, France'},
  d:{fr:"Une couronne briochée à la fleur d'oranger, dorée et légère, née comme gâteau de Pâques dans le Dauphiné. Le nom vient de poignée : la pâte se façonnait à pleines mains, et la couronne se formait autour du poing.",
     en:"A brioche crown scented with orange blossom, golden and light, born as an Easter cake in the Dauphiné. The name comes from poignée, a handful: the dough was shaped with full hands, and the crown formed around the fist."},
  i:[['flour',500,'g'],['sugar',100,'g'],['egg',4,'pc'],['butter',150,'g'],['fresh_yeast',20,'g'],['whole_milk',100,'ml'],['orange_blossom_water',3,'tbsp'],['pearl_sugar',50,'g'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède avec une cuillerée de sucre et laissez-la mousser 15 minutes.","Pétrissez la farine, les œufs, le sucre, le sel et la fleur d'oranger 15 minutes, puis ajoutez le beurre mou en trois fois.","Laissez lever 2 heures, dégazez, et mettez la pâte au froid 4 heures — une pogne se façonne froide, sinon elle colle aux mains.","Formez une boule, percez-la du poing au centre et élargissez le trou jusqu'à un bon diamètre : il se refermera de moitié en poussant.","Laissez pousser 2 heures, dorez, parsemez de sucre en grains et cuisez 35 minutes à 170 °C. La mie doit rester filante et jaune."],
     en:["Dissolve the yeast in warm milk with a spoonful of sugar and let it foam for 15 minutes.","Knead the flour, eggs, sugar, salt and orange blossom water for 15 minutes, then add the softened butter in three goes.","Prove for 2 hours, knock back, and chill the dough for 4 hours — a pogne is shaped cold, otherwise it sticks to the hands.","Form a ball, punch a hole through the centre with your fist and widen it generously: it will close by half as it rises.","Prove for 2 hours, glaze, scatter pearl sugar and bake for 35 minutes at 170°C. The crumb must stay stringy and yellow."]} },

{ id:'pain-d-epices-de-dijon', c:'eu', lat:47.325, lon:5.036, base:10, prep:30, cook:60, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'cake',food:['#8f5a3a','#6f4a2a','#e8dcb8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Pain d’épices de Dijon',en:'Dijon spice bread'},
  p:{fr:'Dijon, Côte-d’Or, France',en:'Dijon, Burgundy, France'},
  d:{fr:"Un pain de miel et d'épices à la farine de froment, plus moelleux que celui de Reims qui se fait au seigle. Les ducs de Bourgogne l'ont rapporté de Flandre au XIVᵉ siècle ; la corporation des pains d'épiciers dijonnais est reconnue en 1711.",
     en:"A honey and spice loaf made with wheat flour, softer than the Reims version made with rye. The dukes of Burgundy brought it back from Flanders in the 14th century; the Dijon guild of spice-bread makers was recognised in 1711."},
  i:[['flour',250,'g'],['honey',300,'g'],['sugar',80,'g'],['egg',1,'pc'],['baking_powder',1,'tsp'],['cinnamon',1,'tsp'],['ground_ginger',1,'tsp'],['cloves',0.5,'tsp'],['nutmeg',0.5,'tsp'],['anise_seeds',1,'tsp'],['orange_zest',1,'pc'],['whole_milk',80,'ml'],['butter',40,'g'],['salt',null,'']],
  s:{fr:["Faites tiédir le miel avec le lait et le beurre, sans dépasser 50 °C : plus chaud, le miel perd son parfum.","Mêlez la farine, le sucre, la levure, le sel et toutes les épices moulues finement.","Versez le miel tiède en filet en mélangeant à la spatule, puis ajoutez l'œuf et le zeste.","Laissez reposer la pâte 24 heures à couvert et à température ambiante : c'est ce repos, et lui seul, qui donne le moelleux et lie les épices.","Versez dans un moule à cake chemisé et cuisez 1 heure à 150 °C. Enveloppez-le tiède dans un linge et attendez deux jours avant de le trancher."],
     en:["Warm the honey with the milk and butter, without going above 50°C: any hotter and the honey loses its scent.","Combine the flour, sugar, baking powder, salt and all the finely ground spices.","Pour in the warm honey in a stream, mixing with a spatula, then add the egg and zest.","Rest the batter for 24 hours, covered, at room temperature: that rest alone gives the softness and marries the spices.","Pour into a lined loaf tin and bake for 1 hour at 150°C. Wrap it warm in a cloth and wait two days before slicing."]} },

{ id:'crepes-de-froment', c:'eu', lat:47.996, lon:-4.098, base:6, prep:70, cook:20, diff:1, tags:['sweet','fast','street'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Crêpes de froment',en:'Wheat crêpes'},
  p:{fr:'Quimper, Finistère, France',en:'Quimper, Brittany, France'},
  d:{fr:"La crêpe sucrée au blé froment, distincte de la galette de sarrasin salée avec laquelle on la confond souvent. En Basse-Bretagne les deux portent le même nom breton, krampouezh ; c'est la farine, et non la garniture, qui les sépare.",
     en:"The sweet wheat crêpe, distinct from the savoury buckwheat galette with which it is often confused. In Lower Brittany both carry the same Breton name, krampouezh; it is the flour, not the filling, that separates them."},
  i:[['flour',250,'g'],['whole_milk',500,'ml'],['egg',3,'pc'],['butter',50,'g'],['sugar',40,'g'],['salted_butter',60,'g'],['rum',20,'ml'],['salt',null,'']],
  s:{fr:["Mêlez la farine, le sucre et le sel, creusez un puits et cassez-y les œufs, puis délayez du centre vers l'extérieur.","Versez le lait petit à petit : ajouté d'un coup, il fait des grumeaux qu'aucun fouet ne rattrape vraiment.","Ajoutez le beurre fondu et le rhum, et laissez reposer la pâte 1 heure — le gluten doit se détendre, sinon les crêpes se rétractent à la cuisson.","Chauffez la crêpière jusqu'à ce qu'une goutte d'eau y danse, graissez d'un chiffon beurré, et étalez une louche au rozell d'un seul geste circulaire.","Une minute d'un côté, trente secondes de l'autre. Beurre demi-sel et sucre, et rien de plus pour la première."],
     en:["Mix the flour, sugar and salt, make a well and break in the eggs, then work outward from the centre.","Add the milk little by little: poured in at once it makes lumps no whisk really rescues.","Add the melted butter and rum, and rest the batter for an hour — the gluten must relax, or the crêpes shrink in the pan.","Heat the griddle until a drop of water dances, grease it with a buttered cloth, and spread a ladleful with the rozell in one circular sweep.","A minute on one side, thirty seconds on the other. Salted butter and sugar, and nothing more for the first one."]} },

{ id:'pate-de-paques-berrichon', c:'eu', lat:46.811, lon:1.691, base:8, prep:60, cook:60, diff:2, tags:['pork','bake','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'pastry',food:['#c9924a','#f2dfa8','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Pâté de Pâques berrichon',en:'Berry Easter pie'},
  p:{fr:'Châteauroux, Indre, France',en:'Châteauroux, Berry, France'},
  d:{fr:"Un pâté en croûte de porc et de veau dans lequel on aligne des œufs durs entiers, si bien que chaque tranche en montre un rond parfait. On le mange le lundi de Pâques, à froid : les œufs marquent la fin du carême, et la coupe doit les révéler intacts.",
     en:"A pork and veal pie in which whole hard-boiled eggs are lined up, so that every slice shows a perfect round. It is eaten cold on Easter Monday: the eggs mark the end of Lent, and the cut must reveal them whole."},
  i:[['shortcrust_pastry',700,'g'],['pork_shoulder',500,'g'],['veal',300,'g'],['smoked_bacon',200,'g'],['egg',8,'pc'],['shallot',3,'pc'],['parsley',5,'tbsp'],['white_wine',80,'ml'],['four_spices',1,'tsp'],['egg_yolk',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites durcir six œufs 9 minutes, rafraîchissez-les à l'eau glacée et écalez-les avec soin : un blanc entamé se voit à la coupe.","Hachez grossièrement les viandes et le lard, mêlez-les à l'échalote, au persil, au vin, au quatre-épices, au sel et à l'œuf restant.","Foncez un moule de pâte, étalez la moitié de la farce, alignez les œufs entiers bout à bout au centre, et couvrez du reste.","Les œufs doivent être noyés et bien centrés : posés trop haut, ils crèvent le couvercle en cuisant.","Refermez, soudez, dorez, ménagez une cheminée et cuisez 15 minutes à 210 °C puis 45 minutes à 170 °C. Se mange froid, le lendemain."],
     en:["Hard-boil six eggs for 9 minutes, refresh them in iced water and peel them carefully: a torn white shows in the slice.","Chop the meats and bacon coarsely, mix them with the shallot, parsley, wine, four-spice, salt and the remaining egg.","Line a mould with pastry, spread half the forcemeat, line the whole eggs end to end down the centre, and cover with the rest.","The eggs must be buried and well centred: set too high, they break through the lid as it bakes.","Close, seal, glaze, cut a chimney and bake 15 minutes at 210°C then 45 minutes at 170°C. Eaten cold, the next day."]} },

{ id:'rillettes-de-tours', c:'eu', lat:47.389, lon:0.691, base:8, prep:30, cook:300, diff:2, tags:['pork','slow','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#8f5a3a','#6f4a2a','#c9924a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Rillettes de Tours',en:'Tours rillettes'},
  p:{fr:'Tours, Indre-et-Loire, France',en:'Tours, Touraine, France'},
  d:{fr:"Des rillettes brunes et sèches, cuites longtemps à découvert jusqu'à ce que la viande caramélise — tout le contraire de celles du Mans, blondes et grasses. Balzac, Tourangeau, les appelait « ce brun confit de cochon » et les tenait pour la gloire de sa province.",
     en:"Brown, dry rillettes, cooked long and uncovered until the meat caramelises — the opposite of those of Le Mans, pale and fatty. Balzac, a Touraine man, called them 'that brown pork confit' and held them to be his province's glory."},
  i:[['pork_shoulder',800,'g'],['pork_belly',400,'g'],['lard',200,'g'],['white_wine',150,'ml'],['thyme',3,'sprig'],['bay_leaf',2,'pc'],['coarse_salt',25,'g'],['bread',400,'g'],['pepper',null,'']],
  s:{fr:["Taillez les viandes en lanières de la taille du doigt, dans le sens des fibres : elles doivent s'effilocher, non se réduire en purée.","Salez-les et laissez-les reposer 12 heures au froid avec le thym et le laurier.","Faites-les fondre dans le saindoux à découvert, à feu très doux, 4 heures, sans jamais couvrir : c'est l'évaporation qui donne la couleur brune.","Montez le feu la dernière demi-heure jusqu'à ce que la viande accroche légèrement au fond et prenne une teinte acajou — c'est là toute la différence avec Le Mans.","Déglacez au vin blanc, effilochez à la fourchette, poivrez, et mettez en pots en tassant. Couvrez de graisse et attendez trois jours."],
     en:["Cut the meats into finger-sized strips along the grain: they must shred, not turn to purée.","Salt them and rest for 12 hours in the cold with the thyme and bay.","Melt them in lard uncovered over very low heat for 4 hours, never putting a lid on: evaporation is what gives the brown colour.","Raise the heat for the last half hour until the meat catches lightly on the base and turns mahogany — that is the whole difference from Le Mans.","Deglaze with white wine, shred with a fork, pepper, and pot them, pressing down. Cover with fat and wait three days."]} },

{ id:'canistrelli', c:'eu', lat:42.303, lon:9.146, base:10, prep:30, cook:25, diff:1, tags:['sweet','bake','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Canistrelli',en:'Canistrelli'},
  p:{fr:'Corte, Haute-Corse, France',en:'Corte, Upper Corsica, France'},
  d:{fr:"Des biscuits corses sablés à l'huile et au vin blanc, parfumés à l'anis, au citron ou aux amandes. Ils ne contiennent ni œuf ni beurre : c'est le vin qui lie la pâte, et c'est pourquoi ils se gardent des semaines dans une boîte de fer.",
     en:"Corsican shortbread biscuits made with oil and white wine, scented with anise, lemon or almonds. They hold neither egg nor butter: the wine binds the dough, which is why they keep for weeks in a tin."},
  i:[['flour',500,'g'],['sugar',200,'g'],['white_wine',150,'ml'],['olive_oil',120,'ml'],['baking_powder',1,'tbsp'],['anise_seeds',1,'tbsp'],['lemon_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Mêlez à sec la farine, le sucre, la levure, le sel et les graines d'anis légèrement écrasées.","Versez l'huile puis le vin blanc et rassemblez la pâte du bout des doigts, sans la pétrir : trop travaillée, elle devient dure au lieu de sablée.","Étalez-la à 1,5 cm et découpez des losanges au couteau, sans emporte-pièce.","Roulez chaque losange dans le sucre en poudre avant de l'enfourner : c'est ce qui donne la croûte craquante.","Cuisez 25 minutes à 180 °C jusqu'à ce qu'ils soient blonds et fendillés. Laissez refroidir complètement sur grille : chauds, ils paraissent mous."],
     en:["Combine the flour, sugar, baking powder, salt and lightly crushed anise seeds dry.","Pour in the oil then the white wine and bring the dough together with your fingertips, without kneading: overworked, it turns hard instead of short.","Roll it 1.5 cm thick and cut diamonds with a knife, not a cutter.","Roll each diamond in caster sugar before it goes in the oven: that is what gives the crackling crust.","Bake for 25 minutes at 180°C until pale gold and cracked. Cool completely on a rack: warm, they seem soft."]} },

{ id:'aziminu', c:'eu', lat:42.694, lon:9.454, base:6, prep:40, cook:45, diff:3, tags:['sea','soup','festive'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4efe3',style:'soup',food:['#c9532c','#e0913a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Aziminu',en:'Aziminu'},
  p:{fr:'Bastia, Haute-Corse, France',en:'Bastia, Upper Corsica, France'},
  d:{fr:"La soupe de poissons de roche corse, cousine de la bouillabaisse mais parfumée au maquis — myrte, immortelle, fenouil sauvage — et sans safran ni orange. Elle se fait de ce que la barque a rapporté : rascasse, congre, chapon, jamais un poisson noble.",
     en:"The Corsican rockfish soup, cousin to bouillabaisse but scented with the maquis — myrtle, immortelle, wild fennel — and without saffron or orange. It is made from whatever the boat brought back: scorpionfish, conger, hogfish, never a noble fish."},
  i:[['rockfish',1.5,'kg'],['potato',800,'g'],['ripe_tomato',500,'g'],['onion',2,'pc'],['garlic',6,'clove'],['fennel',1,'bunch'],['tomato_paste',1,'tbsp'],['olive_oil',100,'ml'],['bay_leaf',2,'pc'],['thyme',3,'sprig'],['bread',400,'g'],['red_pepper',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Écaillez et videz les poissons, gardez les têtes : c'est d'elles que vient le corps du bouillon.","Faites revenir oignon, ail et fenouil à l'huile d'olive, ajoutez la tomate et le concentré, et laissez confire 15 minutes.","Mouillez d'eau bouillante — jamais froide, qui figerait les chairs — et faites cuire les têtes et arêtes 25 minutes.","Passez au moulin à légumes en pressant, remettez sur le feu et faites-y cuire les pommes de terre en rondelles épaisses 15 minutes.","Couchez les poissons entiers dessus pour les 8 dernières minutes, sans remuer. Servez le bouillon d'abord, sur du pain frotté d'ail, et les poissons ensuite."],
     en:["Scale and gut the fish, and keep the heads: they are where the body of the broth comes from.","Soften the onion, garlic and fennel in olive oil, add the tomato and paste, and let it melt down for 15 minutes.","Moisten with boiling water — never cold, which would seize the flesh — and cook the heads and bones for 25 minutes.","Pass through a food mill, pressing hard, return to the heat and cook thick potato rounds in it for 15 minutes.","Lay the whole fish on top for the last 8 minutes, without stirring. Serve the broth first, on garlic-rubbed bread, and the fish after."]} },

{ id:'pulenda', c:'eu', lat:42.371, lon:9.320, base:6, prep:20, cook:45, diff:2, tags:['veg','comfort','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'other',food:['#8f6a4a','#c9a878','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Pulenda',en:'Pulenda'},
  p:{fr:'Piedicroce, Castagniccia, Corse, France',en:'Piedicroce, Castagniccia, Corsica, France'},
  d:{fr:"Une polenta corse à la farine de châtaigne, retournée sur un linge et coupée au fil, servie avec du figatellu et du brocciu. La Castagniccia doit son nom à ses châtaigniers : jusqu'au XXᵉ siècle, ils ont nourri la montagne à la place du blé qu'elle ne pouvait pas faire pousser.",
     en:"A Corsican polenta of chestnut flour, turned out onto a cloth and cut with a thread, served with figatellu and brocciu. The Castagniccia takes its name from its chestnut trees: until the 20th century they fed the mountains in place of the wheat they could not grow."},
  i:[['chestnut_flour',400,'g'],['water',1.2,'l'],['olive_oil',40,'ml'],['brocciu',300,'g'],['coarse_salt',15,'g']],
  s:{fr:["Portez l'eau salée à ébullition et versez la farine de châtaigne en pluie très fine d'une main, en fouettant de l'autre.","La farine de châtaigne prend en grumeaux bien plus vite que le maïs : ne cessez jamais de remuer, et versez lentement.","Travaillez ensuite à la cuillère de bois, en soulevant la masse et en la rabattant, 30 minutes à feu doux.","Elle est prête quand elle se détache d'un bloc des parois du chaudron et qu'une croûte se forme au fond.","Retournez-la sur un linge fariné, formez une boule et coupez-la au fil à couper le beurre — jamais au couteau, qui la déchire. Servez avec du brocciu frais."],
     en:["Bring the salted water to the boil and rain in the chestnut flour very finely with one hand, whisking with the other.","Chestnut flour lumps far faster than maize: never stop stirring, and pour slowly.","Then work with a wooden spoon, lifting the mass and folding it back, for 30 minutes over low heat.","It is ready when it comes away from the sides of the pot in one block and a crust forms on the base.","Turn it out onto a floured cloth, shape a ball and cut it with a butter wire — never a knife, which tears it. Serve with fresh brocciu."]} },

{ id:'cacavellu', c:'eu', lat:42.293, lon:9.185, base:8, prep:180, cook:35, diff:2, tags:['bread','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#f4f0e6','#f2dfa8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Cacavellu',en:'Cacavellu'},
  p:{fr:'Venaco, Haute-Corse, France',en:'Venaco, Upper Corsica, France'},
  d:{fr:"Une couronne briochée de Pâques dans laquelle on enferme un œuf entier, coquille comprise, maintenu par deux bandes de pâte en croix. L'œuf cuit avec le pain ; les parrains l'offraient à leurs filleuls, et sa taille disait l'affection qu'on leur portait.",
     en:"An Easter brioche crown enclosing a whole egg, shell and all, held down by two crossed strips of dough. The egg bakes with the bread; godparents gave them to their godchildren, and the size said how much they were loved."},
  i:[['flour',500,'g'],['sugar',120,'g'],['egg',5,'pc'],['butter',100,'g'],['fresh_yeast',20,'g'],['whole_milk',120,'ml'],['lemon_zest',1,'pc'],['anise_seeds',1,'tsp'],['egg_yolk',1,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, la levure délayée dans le lait tiède, trois œufs, le sucre, le zeste, l'anis et le sel 15 minutes, puis incorporez le beurre.","Laissez lever 2 heures : la pâte doit doubler et sentir l'anis avant qu'on la travaille.","Façonnez une couronne épaisse et posez dessus les deux œufs crus entiers, non lavés, en les enfonçant à moitié dans la pâte.","Croisez au-dessus de chaque œuf deux bandes de pâte et soudez-les fermement : à la cuisson la pâte gonfle et éjecte un œuf mal arrimé.","Laissez pousser 1 heure, dorez le pain seulement — jamais les œufs — et cuisez 35 minutes à 175 °C."],
     en:["Knead the flour, the yeast dissolved in warm milk, three eggs, the sugar, zest, anise and salt for 15 minutes, then work in the butter.","Prove for 2 hours: the dough must double and smell of anise before it is handled.","Shape a thick crown and set the two whole raw eggs on it, unwashed, pressing them halfway into the dough.","Cross two strips of dough over each egg and seal them firmly: as it bakes the dough swells and ejects a badly anchored egg.","Prove for an hour, glaze the bread only — never the eggs — and bake for 35 minutes at 175°C."]} },

{ id:'presskopf-alsacien', c:'eu', lat:48.815, lon:7.790, base:8, prep:60, cook:210, diff:3, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4f0e6',style:'other',food:['#e0a8a0','#f4f0e6','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Presskopf',en:'Presskopf'},
  p:{fr:'Haguenau, Bas-Rhin, France',en:'Haguenau, Alsace, France'},
  d:{fr:"Une hure de porc pressée en gelée, tranchée fine et servie en salade à la vinaigrette d'oignons. Rien ne se perd : la tête entière, la langue, les couennes, et c'est la couenne seule qui fait prendre la gelée, sans un gramme de gélatine ajoutée.",
     en:"A pressed pork head set in its own jelly, sliced thin and served as a salad with onion vinaigrette. Nothing is wasted: the whole head, the tongue, the rinds, and it is the rind alone that sets the jelly, without a gram of added gelatine."},
  i:[['pork_head',1,'pc'],['pork_rinds',300,'g'],['onion',3,'pc'],['carrot',3,'pc'],['leek',2,'pc'],['white_wine',500,'ml'],['bay_leaf',4,'pc'],['cloves',6,'pc'],['parsley',1,'bunch'],['pickles',10,'pc'],['white_vinegar',80,'ml'],['sunflower_oil',100,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites dégorger la tête 12 heures à l'eau froide, en la changeant trois fois, pour la débarrasser du sang.","Pochez-la 3 heures avec les couennes, les légumes, le vin blanc, le laurier et les clous de girofle, sans jamais bouillir : un bouillon trouble donne une gelée trouble.","Désossez à chaud et taillez chairs, langue et couennes en dés d'un centimètre, en écartant les cartilages.","Mêlez-les au persil haché et à un peu de bouillon réduit, tassez dans une terrine et pressez sous un poids 24 heures au froid.","Tranchez très fin et servez avec une vinaigrette d'oignons crus et de cornichons, et du pain de seigle."],
     en:["Soak the head for 12 hours in cold water, changing it three times, to draw out the blood.","Poach it for 3 hours with the rinds, vegetables, white wine, bay and cloves, never boiling: a cloudy broth gives a cloudy jelly.","Bone it while hot and cut the meat, tongue and rind into one-centimetre dice, discarding the cartilage.","Mix them with chopped parsley and a little reduced broth, pack into a terrine and press under a weight for 24 hours in the cold.","Slice very thinly and serve with a vinaigrette of raw onion and gherkin, and rye bread."]} },

{ id:'berawecka', c:'eu', lat:48.583, lon:7.750, base:12, prep:60, cook:60, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'roll',food:['#6f4a2a','#8f5a3a','#c9924a','#e8dcb8'],garnish:'#c9754a'},
  n:{fr:'Berawecka',en:'Berawecka'},
  p:{fr:'Strasbourg, Bas-Rhin, France',en:'Strasbourg, Alsace, France'},
  d:{fr:"Un pain de Noël alsacien fait presque uniquement de fruits secs — poires, figues, pruneaux, noix — que quelques cuillerées de pâte suffisent à tenir ensemble. Berawecka veut dire pain de poires : la poire séchée en est la base, et sa macération dans le kirsch dure une semaine.",
     en:"An Alsatian Christmas loaf made almost entirely of dried fruit — pears, figs, prunes, nuts — held together by a few spoonfuls of dough. Berawecka means pear bread: the dried pear is its base, and its steeping in kirsch lasts a week."},
  i:[['dried_pears',300,'g'],['dried_figs',200,'g'],['prunes',200,'g'],['raisins',150,'g'],['walnuts',150,'g'],['almonds',100,'g'],['flour',150,'g'],['fresh_yeast',10,'g'],['sugar',80,'g'],['kirsch',100,'ml'],['cinnamon',1,'tsp'],['cloves',0.5,'tsp'],['orange_zest',80,'g'],['salt',null,'']],
  s:{fr:["Faites tremper les poires séchées une nuit dans l'eau, puis pochez-les 20 minutes ; gardez l'eau de cuisson.","Coupez tous les fruits en dés, mêlez-les aux fruits secs concassés, aux épices et à l'écorce d'orange, arrosez de kirsch et laissez macérer une semaine au frais, en remuant tous les deux jours.","Préparez une petite pâte levée avec la farine, la levure, le sucre et l'eau de poire tiède, et laissez-la doubler.","Incorporez-la aux fruits : il ne doit y avoir que le strict nécessaire pour les lier, un berawecka est un pain de fruits et non un cake.","Façonnez des pains courts et denses, laissez reposer 1 heure et cuisez 1 heure à 160 °C. Enveloppez-les et attendez trois semaines avant de trancher, très fin."],
     en:["Soak the dried pears overnight in water, then poach them for 20 minutes; keep the cooking water.","Dice all the fruit, mix with the chopped nuts, spices and orange peel, douse with kirsch and steep for a week in the cold, stirring every other day.","Make a small yeasted dough with the flour, yeast, sugar and warm pear water, and let it double.","Fold it into the fruit: there must be no more than is strictly needed to bind, a berawecka is a fruit loaf and not a cake.","Shape short, dense loaves, rest for an hour and bake for an hour at 160°C. Wrap them and wait three weeks before slicing, very thinly."]} },

{ id:'andouille-de-cambrai', c:'eu', lat:50.176, lon:3.235, base:6, prep:45, cook:150, diff:3, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'flat',food:['#8f6a4a','#f0e8d0','#c9924a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Andouille de Cambrai',en:'Cambrai andouille'},
  p:{fr:'Cambrai, Nord, France',en:'Cambrai, Hauts-de-France, France'},
  d:{fr:"Une andouille du Cambrésis faite de chaudins roulés en spirale et fumés doucement, servie froide en tranches avec une vinaigrette à la moutarde. À la différence de celle de Vire, elle n'est pas fumée des semaines : quelques jours suffisent, et la chair reste claire.",
     en:"A Cambrésis andouille of chitterlings rolled in a spiral and gently smoked, served cold in slices with a mustard vinaigrette. Unlike the Vire version it is not smoked for weeks: a few days suffice, and the flesh stays pale."},
  i:[['pork_chitterlings',1.5,'kg'],['pork_stomach',300,'g'],['onion',3,'pc'],['coarse_salt',60,'g'],['thyme',3,'sprig'],['bay_leaf',4,'pc'],['white_wine',400,'ml'],['dijon_mustard',3,'tbsp'],['white_vinegar',60,'ml'],['sunflower_oil',80,'ml'],['pickles',10,'pc'],['bread',300,'g'],['pepper',null,'']],
  s:{fr:["Grattez et retournez les chaudins, lavez-les à l'eau vinaigrée puis salez-les à sec 24 heures avec le thym et le laurier.","Détaillez-les en larges bandes et roulez-les en spirale les unes sur les autres, en serrant progressivement.","Bridez à la ficelle en boudin régulier : c'est la régularité du roulage qui donne la tranche marbrée.","Fumez au froid trois jours au bois de hêtre, puis pochez 2 h 30 dans un bouillon de vin blanc et d'oignon, à 80 °C, sans jamais bouillir.","Laissez refroidir dans le bouillon, tranchez fin et servez avec une vinaigrette moutardée aux oignons et cornichons."],
     en:["Scrape and turn the chitterlings, wash them in vinegared water then dry-salt them for 24 hours with thyme and bay.","Cut them into wide bands and roll them in a spiral one over another, tightening as you go.","Truss with string into an even roll: it is the evenness of the rolling that gives the marbled slice.","Cold-smoke over beech for three days, then poach for 2½ hours in a white wine and onion broth at 80°C, never boiling.","Cool in the broth, slice thinly and serve with a mustard vinaigrette of onion and gherkin."]} },

{ id:'boeuf-miroton', c:'eu', lat:48.858, lon:2.360, base:4, prep:25, cook:45, diff:1, tags:['beef','comfort','bake'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#8f5a3a','#e0b45a','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Bœuf miroton',en:'Bœuf miroton'},
  p:{fr:'Paris, France',en:'Paris, France'},
  d:{fr:"Les restes du pot-au-feu tranchés et gratinés sous une sauce à l'oignon et au vinaigre. C'est le plat du mardi dans les cuisines bourgeoises du XIXᵉ siècle ; il ne se réussit qu'avec de la viande de la veille, une viande fraîche s'y défait.",
     en:"The leftovers of a pot-au-feu sliced and gratinated under an onion and vinegar sauce. It was the Tuesday dish of 19th-century bourgeois kitchens; it only works with yesterday's meat, fresh meat falls apart in it."},
  i:[['beef_chuck',500,'g'],['onion',600,'g'],['butter',50,'g'],['flour',2,'tbsp'],['beef_broth',300,'ml'],['white_vinegar',3,'tbsp'],['dijon_mustard',1,'tbsp'],['breadcrumbs',60,'g'],['pickles',6,'pc'],['parsley',3,'tbsp'],['potato',800,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Émincez les oignons finement et faites-les blondir au beurre 25 minutes : ils doivent dorer, pas seulement fondre — c'est là que naît le goût du plat.","Singez de farine, laissez-la cuire deux minutes, puis mouillez du bouillon de pot-au-feu et laissez épaissir 10 minutes.","Ajoutez le vinaigre et la moutarde hors du feu : la sauce miroton doit piquer franchement, sinon le bœuf bouilli reste fade.","Tranchez le bœuf froid en lamelles de 5 mm — chaud, il s'effiloche — et rangez-les en écailles dans un plat beurré.","Nappez de sauce, parsemez de chapelure et gratinez 15 minutes à 200 °C. Cornichons et persil au moment de servir."],
     en:["Slice the onions finely and let them turn golden in butter for 25 minutes: they must colour, not merely soften — that is where the dish's flavour is born.","Dust with flour, cook it for two minutes, then moisten with the pot-au-feu broth and let it thicken for 10 minutes.","Add the vinegar and mustard off the heat: a miroton sauce must be frankly sharp, or the boiled beef stays dull.","Slice the cold beef 5 mm thick — hot, it shreds — and lay the slices overlapping in a buttered dish.","Coat with the sauce, scatter breadcrumbs and gratinate for 15 minutes at 200°C. Gherkins and parsley on serving."]} },

{ id:'macarons-de-nancy', c:'eu', lat:48.692, lon:6.184, base:12, prep:40, cook:20, diff:2, tags:['sweet','bake','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#f0e8d0','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Macarons de Nancy',en:'Macarons of Nancy'},
  p:{fr:'Nancy, Meurthe-et-Moselle, France',en:'Nancy, Lorraine, France'},
  d:{fr:"Un macaron ancien, craquelé, sans coque lisse ni garniture, fait de trois ingrédients seulement. Deux religieuses chassées de leur couvent par la Révolution le vendirent pour vivre à Nancy en 1793 : on les appela les sœurs macarons, et la recette n'a pas bougé.",
     en:"An old-style macaron, cracked, with no smooth shell and no filling, made of three ingredients only. Two nuns turned out of their convent by the Revolution sold them to live in Nancy in 1793: they were called the macaron sisters, and the recipe has not moved since."},
  i:[['ground_almonds',250,'g'],['sugar',250,'g'],['egg_white',3,'pc'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Mêlez la poudre d'amande et le sucre, et ajoutez les blancs non montés, simplement détendus à la fourchette.","Ne montez surtout pas les blancs en neige : c'est ce qui distingue le macaron de Nancy du macaron parisien, et une meringue donnerait une coque lisse.","Travaillez à la spatule jusqu'à une pâte épaisse et collante, et laissez-la reposer 30 minutes.","Déposez des tas d'une cuillerée sur du papier cuisson, bien espacés, sans les lisser : la fissure doit venir seule.","Cuisez 18 minutes à 160 °C. Ils doivent rester moelleux au centre — sortez-les quand le dessus est blond mais le cœur encore souple."],
     en:["Mix the ground almonds and sugar, and add the whites unbeaten, merely loosened with a fork.","On no account whip the whites: that is what separates the Nancy macaron from the Parisian one, and a meringue would give a smooth shell.","Work with a spatula to a thick, sticky paste, and rest it for 30 minutes.","Drop spoonfuls onto baking paper, well spaced, without smoothing them: the crack must come by itself.","Bake for 18 minutes at 160°C. They must stay soft in the middle — take them out when the top is golden but the centre still yielding."]} },

{ id:'souffle-au-fromage', c:'eu', lat:48.866, lon:2.320, base:4, prep:25, cook:30, diff:3, tags:['cheese','bake','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4f0e6',style:'other',food:['#e8c46a','#f2dfa8','#f4f0e6','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Soufflé au fromage',en:'Cheese soufflé'},
  p:{fr:'Paris, France',en:'Paris, France'},
  d:{fr:"Une béchamel allégée de blancs montés, qui triple de volume au four et retombe en trois minutes. Le mot apparaît chez Beauvilliers en 1814 : c'est le premier plat français dont la réussite se mesure à la seconde près, et l'on attend le soufflé, jamais l'inverse.",
     en:"A béchamel lightened with whipped whites, which triples in the oven and falls within three minutes. The word appears in Beauvilliers in 1814: the first French dish whose success is measured to the second, and one waits for the soufflé, never the reverse."},
  i:[['butter',60,'g'],['flour',50,'g'],['whole_milk',400,'ml'],['egg_yolk',4,'pc'],['egg_white',6,'pc'],['gruyere_cheese',120,'g'],['comte_cheese',60,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Beurrez le moule de bas en haut, en bandes verticales, et sucrez-le de fromage râpé : le soufflé s'accroche aux parois pour monter.","Faites une béchamel épaisse, laissez-la tiédir, puis incorporez les jaunes un à un, le fromage, la muscade et le poivre.","Montez les blancs avec une pincée de sel jusqu'au bec d'oiseau, fermes mais non granuleux — trop montés, ils ne se mêlent plus.","Détendez la base d'un tiers des blancs au fouet, puis incorporez le reste à la spatule en soulevant, en une vingtaine de gestes seulement.","Emplissez aux trois quarts, passez le pouce le long du bord pour décoller la pâte, et cuisez 30 minutes à 190 °C sans jamais ouvrir la porte. Servez dans la minute."],
     en:["Butter the dish from bottom to top in vertical strokes, and line it with grated cheese: the soufflé grips the sides to climb.","Make a thick béchamel, let it cool a little, then beat in the yolks one at a time, the cheese, nutmeg and pepper.","Whip the whites with a pinch of salt to the bird's beak, firm but not grainy — overbeaten, they will no longer fold in.","Loosen the base with a third of the whites using the whisk, then fold in the rest with a spatula, lifting, in some twenty movements only.","Fill three-quarters full, run your thumb round the rim to free the mixture, and bake 30 minutes at 190°C without once opening the door. Serve within the minute."]} },

{ id:'tarte-normande', c:'eu', lat:49.146, lon:0.226, base:8, prep:35, cook:45, diff:1, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#e0b45a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tarte normande',en:'Norman apple tart'},
  p:{fr:'Lisieux, Calvados, France',en:'Lisieux, Normandy, France'},
  d:{fr:"Une tarte aux pommes noyée d'un flan à la crème et parfumée au calvados. Le choix de la pomme fait tout : une reinette ou une boskoop tiennent à la cuisson, une golden se défait en compote et le flan devient aqueux.",
     en:"An apple tart flooded with a cream custard and scented with calvados. The choice of apple is everything: a reinette or a boskoop holds its shape, a golden collapses into purée and the custard turns watery."},
  i:[['shortcrust_pastry',300,'g'],['apple',6,'pc'],['sugar',150,'g'],['egg',4,'pc'],['heavy_cream',200,'ml'],['butter',50,'g'],['calvados',40,'ml'],['ground_almonds',50,'g'],['cinnamon',1,'tsp']],
  s:{fr:["Foncez le moule, piquez le fond et faites-le cuire à blanc 12 minutes à 190 °C sous des billes de cuisson.","Saupoudrez le fond précuit de poudre d'amande : elle boira le jus des pommes et empêchera la pâte de détremper.","Coupez les pommes en quartiers épais et faites-les revenir 5 minutes au beurre avec un peu de sucre, puis flambez au calvados.","Rangez-les en rosace serrée et versez l'appareil fait des œufs, du sucre restant, de la crème et de la cannelle.","Cuisez 45 minutes à 180 °C. Le flan doit encore trembler au centre à la sortie : il finit de prendre en refroidissant."],
     en:["Line the tin, prick the base and blind-bake it for 12 minutes at 190°C under baking beans.","Dust the pre-baked base with ground almonds: they will drink the apple juices and stop the pastry going soggy.","Cut the apples into thick wedges and cook them 5 minutes in butter with a little sugar, then flame with calvados.","Arrange them in a tight rosette and pour over the custard of eggs, remaining sugar, cream and cinnamon.","Bake for 45 minutes at 180°C. The custard should still tremble at the centre as it comes out: it finishes setting as it cools."]} },

{ id:'gateau-a-la-broche', c:'eu', lat:42.905, lon:0.365, base:12, prep:60, cook:120, diff:3, tags:['sweet','festive','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'cake',food:['#e0b45a','#c9924a','#f2dfa8','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Gâteau à la broche',en:'Spit cake'},
  p:{fr:'Arreau, Hautes-Pyrénées, France',en:'Arreau, Pyrenees, France'},
  d:{fr:"Un cône de pâte hérissé de pointes, construit couche après couche sur une broche tournant devant le feu de bois. Chaque louche versée sur le cône brûlant durcit avant la suivante ; les pointes ne sont pas décoratives, ce sont les coulures figées de la pâte.",
     en:"A spiked cone of cake built layer upon layer on a spit turning before a wood fire. Each ladleful poured on the scalding cone hardens before the next; the spikes are not decoration, they are the drips of batter set hard."},
  i:[['flour',500,'g'],['sugar',250,'g'],['egg',12,'pc'],['butter',250,'g'],['baking_powder',1,'tbsp'],['rum',50,'ml'],['orange_blossom_water',2,'tbsp'],['lemon_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Battez longuement les œufs entiers avec le sucre, au moins 10 minutes, jusqu'à ce que le mélange triple et forme un ruban épais.","Incorporez le beurre fondu tiède, puis la farine tamisée, le rhum, la fleur d'oranger et le zeste : la pâte doit couler du fouet en ruban continu.","Chemisez le cône de papier beurré et faites-le tourner devant les braises jusqu'à ce qu'il soit brûlant.","Versez une louche de pâte sur le cône en rotation et attendez qu'elle dore complètement avant la suivante : quinze à vingt couches, deux heures de patience.","Laissez refroidir sur la broche avant de démouler. Le gâteau se garde un mois et se coupe en travers, à la scie ou au grand couteau."],
     en:["Beat whole eggs with the sugar at length, at least 10 minutes, until the mixture triples and ribbons thickly.","Fold in the warm melted butter, then the sifted flour, rum, orange blossom water and zest: the batter must run off the whisk in an unbroken ribbon.","Line the cone with buttered paper and turn it before the coals until it is scalding.","Pour a ladleful of batter onto the turning cone and wait for it to brown completely before the next: fifteen to twenty layers, two hours of patience.","Cool on the spit before unmoulding. The cake keeps a month and is cut crosswise, with a saw or a long knife."]} },

{ id:'fouace-nantaise', c:'eu', lat:47.213, lon:-1.560, base:8, prep:150, cook:30, diff:2, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Fouace nantaise',en:'Nantes fouace'},
  p:{fr:'Nantes, Loire-Atlantique, France',en:'Nantes, Pays de la Loire, France'},
  d:{fr:"Une galette briochée à la fleur d'oranger, façonnée en étoile à six branches et cuite à plat. Rabelais lui a donné sa célébrité : la guerre picrocholine du Gargantua éclate pour quelques fouaces refusées à des bergers.",
     en:"An orange-blossom brioche flatbread, shaped as a six-pointed star and baked flat. Rabelais made it famous: the Picrocholine war in Gargantua breaks out over a few fouaces refused to some shepherds."},
  i:[['flour',500,'g'],['sugar',150,'g'],['egg',4,'pc'],['butter',150,'g'],['fresh_yeast',20,'g'],['whole_milk',100,'ml'],['orange_blossom_water',3,'tbsp'],['egg_yolk',1,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, la levure délayée dans le lait tiède, les œufs, le sucre, le sel et la fleur d'oranger 12 minutes.","Incorporez le beurre mou et pétrissez encore 8 minutes, jusqu'à ce que la pâte se décolle nettement.","Laissez lever 1 h 30, dégazez, puis abaissez la pâte en disque épais de 3 cm sur une plaque.","Découpez six pointes régulières au couteau, en partant du bord vers le centre sans atteindre le milieu : c'est cette forme d'étoile qui fait la fouace.","Laissez pousser 1 heure, dorez au jaune et cuisez 30 minutes à 180 °C. Se mange tiède, avec du beurre demi-sel."],
     en:["Knead the flour, the yeast dissolved in warm milk, the eggs, sugar, salt and orange blossom water for 12 minutes.","Work in the softened butter and knead 8 minutes more, until the dough clearly leaves the bowl.","Prove for 1½ hours, knock back, then roll the dough into a 3 cm thick disc on a tray.","Cut six even points with a knife, from the edge toward the centre without reaching the middle: that star shape is what makes a fouace.","Prove for an hour, glaze with yolk and bake for 30 minutes at 180°C. Eaten warm, with salted butter."]} },

{ id:'briau-sarthois', c:'eu', lat:48.003, lon:0.204, base:6, prep:35, cook:45, diff:1, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'pastry',food:['#4f6f3a','#f2dfa8','#7fae5a','#e8dcb8'],garnish:'#6fbf8f'},
  n:{fr:'Briau sarthois',en:'Sarthe briau'},
  p:{fr:'Le Mans, Sarthe, France',en:'Le Mans, Sarthe, France'},
  d:{fr:"Un flan salé d'épinards, de lardons et de crème sur une pâte brisée, cuit dans un plat creux. Le briau est le plat des jardins de la Sarthe quand les épinards montent : on en fait autant qu'il en pousse, et il se mange tiède ou froid.",
     en:"A savoury custard of spinach, bacon and cream on shortcrust, baked in a deep dish. The briau is the Sarthe garden dish for when the spinach bolts: as much is made as grows, and it is eaten warm or cold."},
  i:[['shortcrust_pastry',300,'g'],['spinach',800,'g'],['smoked_bacon',200,'g'],['egg',4,'pc'],['heavy_cream',200,'ml'],['onion',1,'pc'],['butter',30,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tomber les épinards à la poêle en trois fois, sans eau, puis pressez-les à fond entre vos mains.","Un kilo d'épinards crus donne à peine trois cents grammes une fois pressés : c'est normal, et c'est l'eau restante qui ruinerait le flan.","Faites rissoler les lardons et l'oignon au beurre, et mêlez-les aux épinards hachés au couteau.","Battez les œufs avec la crème, la muscade et le poivre, et ne salez qu'à peine — les lardons salent déjà.","Garnissez le fond de pâte, versez l'appareil et cuisez 45 minutes à 180 °C. La pointe d'un couteau doit ressortir sèche."],
     en:["Wilt the spinach in a pan in three batches, without water, then press it hard between your hands.","A kilo of raw spinach gives barely three hundred grams once pressed: that is normal, and it is the remaining water that would ruin the custard.","Fry the bacon and onion in butter, and mix them with the knife-chopped spinach.","Beat the eggs with the cream, nutmeg and pepper, and salt barely — the bacon salts it already.","Fill the pastry case, pour in the custard and bake for 45 minutes at 180°C. A knife point must come out dry."]} },

{ id:'prefou-vendeen', c:'eu', lat:46.995, lon:-2.245, base:6, prep:90, cook:20, diff:1, tags:['bread','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#f4f0e6','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Préfou',en:'Préfou'},
  p:{fr:'Noirmoutier, Vendée, France',en:'Noirmoutier, Vendée, France'},
  d:{fr:"Un pain plat fendu et garni d'un beurre d'ail, réchauffé au four et rompu à la main. Il tire son nom du pré-four : les boulangers vendéens y jetaient un morceau de pâte pour éprouver la chaleur du four, et le mangeaient avec ce qu'ils avaient sous la main.",
     en:"A flat bread split and filled with garlic butter, warmed through and torn by hand. Its name comes from pré-four, before the oven: Vendée bakers threw in a piece of dough to test the heat, and ate it with whatever came to hand."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['warm_water',280,'ml'],['salted_butter',200,'g'],['garlic',6,'clove'],['parsley',3,'tbsp'],['olive_oil',20,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte à pain souple et laissez-la lever 1 heure.","Étalez-la en deux galettes ovales de 1,5 cm et cuisez-les 10 minutes à 220 °C : elles doivent rester très pâles, à peine prises.","C'est cette précuisson courte qui compte — un pain doré ne s'ouvrira plus sans se briser.","Travaillez le beurre demi-sel en pommade avec l'ail pilé finement et le persil, sans rien ajouter d'autre.","Fendez chaque galette tiède à l'horizontale, tartinez généreusement, refermez et repassez 8 minutes à 200 °C, jusqu'à ce que le beurre bouillonne sur les bords."],
     en:["Knead a soft bread dough and prove it for an hour.","Roll it into two oval flatbreads 1.5 cm thick and bake them 10 minutes at 220°C: they must stay very pale, barely set.","That short pre-bake is what matters — a browned bread will not open again without breaking.","Cream the salted butter with finely crushed garlic and parsley, adding nothing else.","Split each warm flatbread horizontally, spread generously, close and return for 8 minutes at 200°C, until the butter bubbles at the edges."]} },

{ id:'tourton-des-alpes', c:'eu', lat:44.559, lon:6.079, base:6, prep:60, cook:20, diff:2, tags:['veg','fry','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tourtons du Champsaur',en:'Champsaur tourtons'},
  p:{fr:'Gap, Hautes-Alpes, France',en:'Gap, Southern Alps, France'},
  d:{fr:"De petits coussins de pâte fine frits, salés à la pomme de terre ou sucrés à la pomme, qu'on appelle les oreillers de l'enfant Jésus. Ils se faisaient à la veillée dans le Champsaur, à plusieurs mains : l'un abaisse, l'autre garnit, un troisième frit.",
     en:"Small fried pillows of thin dough, savoury with potato or sweet with apple, known as the infant Jesus's pillows. They were made at evening gatherings in the Champsaur, several pairs of hands at once: one rolls, one fills, a third fries."},
  i:[['flour',250,'g'],['egg',1,'pc'],['butter',50,'g'],['water',80,'ml'],['potato',400,'g'],['tome_fraiche',150,'g'],['parsley',4,'tbsp'],['apple',3,'pc'],['sugar',80,'g'],['cinnamon',1,'tsp'],['frying_oil',800,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez farine, œuf, beurre fondu, eau et sel en une pâte lisse, et laissez-la reposer 1 heure sous un linge.","Préparez les deux farces : pommes de terre écrasées au fromage et au persil pour la salée, pommes fondues au sucre et à la cannelle pour la sucrée.","Abaissez la pâte le plus finement possible — on doit deviner la main au travers — et découpez des carrés de 8 cm.","Déposez une cuillerée de farce, humectez les bords, refermez en rectangle et soudez à la fourchette : un tourton mal soudé s'ouvre dans la friture.","Faites frire à 175 °C, 2 minutes par face, jusqu'à ce qu'ils boursouflent et dorent. Égouttez et servez brûlants."],
     en:["Knead the flour, egg, melted butter, water and salt to a smooth dough, and rest it for an hour under a cloth.","Prepare the two fillings: mashed potato with cheese and parsley for the savoury, apples softened with sugar and cinnamon for the sweet.","Roll the dough as thinly as possible — you should half see your hand through it — and cut 8 cm squares.","Set a spoonful of filling on each, damp the edges, fold into a rectangle and seal with a fork: a badly sealed tourton opens in the fryer.","Fry at 175°C, 2 minutes a side, until they blister and brown. Drain and serve scalding."]} },

{ id:'tarte-tropezienne', c:'eu', lat:43.269, lon:6.640, base:8, prep:180, cook:25, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e0b45a','#f4f0e6','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tarte tropézienne',en:'Tarte tropézienne'},
  p:{fr:'Saint-Tropez, Var, France',en:'Saint-Tropez, French Riviera, France'},
  d:{fr:"Une brioche au sucre en grains fendue et garnie d'une crème mi-pâtissière mi-beurre. Créée en 1955 par un pâtissier polonais installé à Saint-Tropez, elle fut baptisée par Brigitte Bardot pendant le tournage d'Et Dieu créa la femme.",
     en:"A pearl-sugar brioche split and filled with a cream half pastry cream, half butter. Created in 1955 by a Polish pastry cook settled in Saint-Tropez, it was named by Brigitte Bardot during the filming of And God Created Woman."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['sugar',100,'g'],['egg',4,'pc'],['butter',150,'g'],['whole_milk',500,'ml'],['egg_yolk',4,'pc'],['cornstarch',50,'g'],['heavy_cream',200,'ml'],['orange_blossom_water',2,'tbsp'],['pearl_sugar',60,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez la brioche 15 minutes, incorporez le beurre, laissez lever 2 heures puis reposer une nuit au froid.","Faites une crème pâtissière au lait, aux jaunes, au sucre, à la fécule et à la vanille, et laissez-la refroidir complètement, filmée au contact.","Détendez-la au fouet, puis incorporez la crème fouettée ferme et la fleur d'oranger : c'est ce mélange des deux crèmes qui fait la légèreté.","Abaissez la brioche en disque de 2 cm, laissez pousser 1 h 30, parsemez de sucre en grains et cuisez 25 minutes à 175 °C.","Fendez-la en deux à l'horizontale une fois froide, garnissez généreusement à la poche et laissez prendre 2 heures au frais avant de servir."],
     en:["Knead the brioche for 15 minutes, work in the butter, prove for 2 hours then rest overnight in the cold.","Make a pastry cream with the milk, yolks, sugar, cornstarch and vanilla, and cool it completely, covered in contact.","Loosen it with a whisk, then fold in the stiffly whipped cream and the orange blossom water: that marriage of two creams is what gives the lightness.","Roll the brioche into a 2 cm disc, prove for 1½ hours, scatter pearl sugar and bake 25 minutes at 175°C.","Split it horizontally once cold, pipe in the filling generously and chill for 2 hours before serving."]} }
];
